def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: Nanoseconds since the Unix epoch (or desired epoch).
    :param tz: Optional timezone for the resulting time.
    :return: datetime.time object or None if input is None.
    """
    if nanoseconds is None:
        return None
    # Convert nanoseconds to seconds
    seconds = nanoseconds / 1_000_000_000
    # If a timezone is supplied, use it; otherwise use the local timezone
    if tz is not None:
        # If tz is a string, attempt to interpret common timezone names
        if isinstance(tz, str):
            # Simple handling: 'UTC' or 'GMT'
            if tz.upper() in ('UTC', 'GMT'):
                tz = datetime.timezone.utc
            else:
                raise ValueError(f"Unsupported timezone string: {tz}")
        return datetime.datetime.fromtimestamp(seconds, tz).time()
    else:
        # Default to local system timezone (no tzinfo)
        return datetime.datetime.fromtimestamp(seconds).time()

