@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Assume the class has a mapping of protocol version tuples to handler classes
    # stored in the class attribute `_protocol_handlers`. This attribute should be
    # defined elsewhere in the class hierarchy.
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        handler = getattr(cls, "_protocol_handlers", {}).get(protocol_version)
        return {protocol_version: handler} if handler is not None else {}
    else:
        return dict(getattr(cls, "_protocol_handlers", {}))

if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError("protocol_version must be a tuple (major, minor)")
            handler = cls._handlers.get(protocol_version)
            return {protocol_version: handler} if handler else {}
        # Return a copy to prevent accidental modifications
        return dict(cls._handlers)

def unit_of_work(metadata=None, timeout=None):
    """Decorator for transaction functions that allows extra control over how the transaction is carried out.

    :param metadata: A dictionary with metadata to attach to the transaction. Optional.
    :param timeout: The transaction timeout in seconds. Optional.
    :raises TypeError: If metadata is not a dict or timeout is not a number.
    :raises ValueError: If timeout is negative.
    """
    # Validate metadata
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("metadata must be a dictionary or None")
    # Validate timeout
    if timeout is not None:
        try:
            timeout_val = float(timeout)
        except Exception:
            raise TypeError("timeout must be a number or None")
        if timeout_val < 0:
            raise ValueError("timeout cannot be negative")
    else:
        timeout_val = None

    def decorator(fn):
        from functools import wraps

        @wraps(fn)
        def wrapper(*args, **kwargs):
            # The wrapped function is expected to receive a transaction object as the first argument.
            # Return its result directly.
            return fn(*args, **kwargs)

        # Attach metadata and timeout attributes for use by the session's execute methods.
        wrapper._nn_meta = metadata
        wrapper._nn_timeout = timeout_val
        return wrapper

    return decorator

