    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Retrieve the underlying value storage.  Some implementations
    # keep the values in ``self._values``; others may use ``self._data``.
    data = getattr(self, "_values", None)
    if data is None:
        data = getattr(self, "_data", None)
    if data is None:
        raise AttributeError("Record object has no values to return")

    # If there are no filtering keys, just return all values.
    if not keys:
        if isinstance(data, dict):
            return list(data.values())
        # For list/tuple-like containers we return a copy.
        return list(data)

    # Build the result list based on the type of the underlying
    # container and the nature of the requested keys.
    result = []

    # List/tuple-like storage
    if isinstance(data, (list, tuple)):
        col_names = getattr(self, "_column_names", None)
        for key in keys:
            if isinstance(key, int):
                # Index-based access
                if key < 0 or key >= len(data):
                    raise IndexError(f"Index {key} out of range")
                result.append(data[key])
            else:
                # Key-based access – requires column names mapping
                if col_names is None:
                    raise TypeError(
                        "Record values are indexed by integer; no column names available"
                    )
                try:
                    idx = col_names.index(key)
                except ValueError:
                    raise KeyError(f"Column {key!r} not found") from None
                result.append(data[idx])

    # Dictionary-like storage
    elif isinstance(data, dict):
        for key in keys:
            try:
                result.append(data[key])
            except KeyError:
                raise KeyError(f"Key {key!r} not found") from None

    else:
        raise TypeError("Unsupported data type for record values")

    return result

def values(self, *keys):
