    # Attempt to use a dedicated dictionary attribute; fall back to the
    # instance itself if it behaves like a mapping.
    mapping = getattr(self, "_dict", None)
    if mapping is None:
        mapping = self

    # Return all values if no filtering keys are supplied.
    if not keys:
        try:
            return list(mapping.values())
        except AttributeError:
