def data(self, *keys):
    """Return the keys and values of this record as a dictionary.

    Keys may be field names or integer indices.  If no keys are
    supplied all fields are returned.  Missing names result in
    ``None`` values and out‑of‑range indices raise :class:`IndexError`.
    """
    # Expect the record to keep an ordered list of field names and
    # a tuple/list of the corresponding values.  The attributes might
    # be called ``_keys``/``_values`` or ``columns``/``tuple_values``;
    # use the most common ones here.
    keys_attr = getattr(self, "_keys", None)
    values_attr = getattr(self, "_values", None)
    if keys_attr is None or values_attr is None:
        # Try alternative attribute names
        keys_attr = getattr(self, "columns", None)
        values_attr = getattr(self, "tuple_values", getattr(self, "tuple", None))
    if keys_attr is None or values_attr is None:
        raise AttributeError("Record object missing expected data storage attributes")

    all_keys = list(keys_attr)
    all_values = list(values_attr)

    if not keys:
        # Return a mapping of every field name to its value
        return dict(zip(all_keys, all_values))

    # Build a quick map from field name -> index for fast lookup
    name_to_index = {name: i for i, name in enumerate(all_keys)}
    result = {}

    for key in keys:
        if isinstance(key, int):
            # Index access: validate bounds
            if key < 0 or key >= len(all_values):
                raise IndexError(f"Index {key} out of bounds")
            result[all_keys[key]] = all_values[key]
        else:
            # Name access
            if key in name_to_index:
                idx = name_to_index[key]
                result[key] = all_values[idx]
            else:
                result[key] = None

    return result

def data(self, *keys):
