    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Attempt to find the record's internal data structures
    fields = getattr(self, "_fields", None)
    data_seq = getattr(self, "_data", None)

    # Fallback: if the instance is a mapping, just return the mapping
    if fields is None or data_seq is None:
        if isinstance(self, dict):
            if not keys:
                return dict(self)
            # Only return requested keys, missing keys become None
            return {k: self.get(k, None) for k in keys}
        raise AttributeError(
            "Record object must expose `_fields` and `_data` attributes or be a dict"
        )

    if not keys:
        return dict(zip(fields, data_seq))

    # Build a name-to-index map to speed lookups
    field_map = {name: idx for idx, name in enumerate(fields)}

    result = {}
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(data_seq):
                raise IndexError(f"Index {key} out of range for data sequence of length {len(data_seq)}")
            name = fields[key]
            result[name] = data_seq[key]
        else:
            if key in field_map:
                result[key] = data_seq[field_map[key]]
            else:
                result[key] = None
    return result

def data(self, *keys):
    """Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """

    # If no keys are supplied, return all field-value pairs.
    if not keys:
        return {k: v for k, v in zip(self.schema, self._data)}

    result = {}
    for key in keys:
        if isinstance(key, int):
            # Integer key is treated as an index.
            try:
                value = self._data[key]
            except IndexError:
                raise IndexError(f"Index {key} out of range")
            # Retrieve the corresponding field name.
            field_name = self.schema[key]
            result[field_name] = value
        else:
            # Non‑integer key is treated as a field name.
            if key in self.schema:
                idx = self.schema.index(key)
                result[key] = self._data[idx]
            else:
                result[key] = None
    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
        """
        Appends a DISCARD message to the output queue.

        :param n: number of records to discard, default = -1 (ALL)
        :param qid: query ID to discard for, default = -1 (last query)
        :param dehydration_hooks: Hooks to dehydrate types (dict from type to function).
        :param hydration_hooks: Hooks to hydrate types (mapping from type to function).
        :param handlers: handler functions passed into the returned Response object
        """
        if n < -1:
            raise ValueError("n must be -1 (ALL) or a non‑negative integer")

        # Resolve the query id; if -1 use the most recent one if available
        query_id = qid
        if qid == -1 and hasattr(self, "_last_qid"):
            query_id = getattr(self, "_last_qid")

        # Build the discard command structure (using a simple dict for the queue)
        command = {"type": "DISCARD", "n": n, "qid": query_id}

        # Append to the output queue – try common attribute names
        if hasattr(self, "_out"):
            self._out.append(command)
        elif hasattr(self, "_queue"):
            self._queue.append(command)
        else:
            # Fallback: create an outbound list attribute
            setattr(self, "_out", [command])

        # Return a Response object if the infrastructure exists; otherwise None
        try:
            # Assume a Response constructor is available in the context
            return Response(self, handlers, dehydration_hooks, hydration_hooks)
        except Exception:
            # If Response is not defined, simply return None
            return None

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.
    """
    params = {}

    if mode is not None:
        params["mode"] = mode
    if bookmarks is not None:
        try:
            params["bookmarks"] = list(bookmarks)
        except TypeError:
            raise ValueError("bookmarks must be an iterable") from None
    if metadata is not None:
        params["metadata"] = metadata
    if timeout is not None:
        params["timeout"] = timeout
    if db is not None:
        params["database"] = db
    if imp_user is not None:
        params["impersonatedUser"] = imp_user
    if dehydration_hooks is not None:
        params["dehydrationHooks"] = dehydration_hooks
    if hydration_hooks is not None:
        params["hydrationHooks"] = hydration_hooks

    # Queue the BEGIN message.  The protocol expects a 12‑byte marker
    # followed by a packstream‑encoded map of the params.
    self._out_queue.append(("BEGIN", params))

    # Return a Response object that will produce the server’s reply.
    return Response(self, handlers)

