def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if maxsize <= 0:
        raise ValueError("maxsize must be > 0")
    if ttl <= 0:
        raise ValueError("ttl must be > 0")

    def decorating_function(user_function):
        cache = collections.OrderedDict()

        @functools.wraps(user_function)
        def wrapper(*args, **kwargs):
            # Create a key that respects typing if requested
            if typed:
                key = (tuple(args), tuple(sorted((k, type(v)) for k, v in kwargs.items())))
            else:
                key = (tuple(args), tuple(sorted(kwargs.items())))
            current_time = timer()

            # Check cache entry
            if key in cache:
                value, timestamp = cache[key]
                # If expired, remove entry
                if current_time - timestamp >= ttl:
                    del cache[key]
                else:
                    # Move to end to mark as recently used
                    cache.move_to_end(key)
                    return value

            # Cache miss: compute value
            result = user_function(*args, **kwargs)
            cache[key] = (result, current_time)
            cache.move_to_end(key)

            # Evict least-recently used item if exceeded maxsize
            if len(cache) > maxsize:
                cache.popitem(last=False)

            return result

        def cache_info():
            """Report cache statistics"""
            hits = getattr(wrapper, "hits", 0)
            misses = getattr(wrapper, "misses", 0)
            return collections.namedtuple('CacheInfo', 'hits misses maxsize len')(
                hits, misses, maxsize, len(cache))

        def cache_clear():
            """Clear the cache and stats"""
            cache.clear()
            wrapper.hits = 0
            wrapper.misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        wrapper.hits = 0
        wrapper.misses = 0

        # Wrap to keep track of hits/misses
        @functools.wraps(user_function)
        def wrapper_with_stats(*args, **kwargs):
            key = (tuple(args), tuple(sorted(kwargs.items())))
            if key in cache:
                wrapper.hits += 1
                return wrapper(*args, **kwargs)
            else:
                wrapper.misses += 1
                return wrapper(*args, **kwargs)

        # Replace wrapper with stats-enabled version
        return wrapper_with_stats

    return decorating_function

