def _legacy_mergeOrderings(orderings):
    """
    Merge multiple orderings so that within-ordering order is preserved.
    """
    # Build directed graph of precedence constraints
    graph = {}
    indegree = {}
    first_seen = {}
    count = 0
    for ordering in orderings:
        for i, item in enumerate(ordering):
            if item not in first_seen:
                first_seen[item] = count
                count += 1
            if i + 1 < len(ordering):
                a, b = ordering[i], ordering[i + 1]
                graph.setdefault(a, set()).add(b)
                indegree[b] = indegree.get(b, 0) + 1
                indegree.setdefault(a, 0)
    # Ensure all items appear in indegree dict
    for item in first_seen:
        indegree.setdefault(item, 0)

    # Kahn's algorithm with deterministic tie‑breaking by first appearance
    zero = [node for node, deg in indegree.items() if deg == 0]
    zero.sort(key=lambda x: first_seen[x])
    result = []
    while zero:
        node = zero.pop(0)
        result.append(node)
        for neigh in sorted(graph.get(node, []), key=lambda x: first_seen[x]):
            indegree[neigh] -= 1
            if indegree[neigh] == 0:
                zero.append(neigh)
        zero.sort(key=lambda x: first_seen[x])

    if len(result) != len(first_seen):
        raise ValueError("Orderings contain a cycle")
    return result

def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent.
    The resulting list keeps only those base classes that are not
    superclasses of any other base in the original list, preserving
    the original order of the first occurrences.
    """
    cls_tuple = tuple(classes)
    return tuple(
        base
        for i, base in enumerate(cls_tuple)
        if not any(issubclass(other, base) for j, other in enumerate(cls_tuple) if j != i)
    )

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    minimal = []
    for cls in classes:
        if cls in seen:
            continue
        if any(issubclass(cls, base) for base in minimal):
            continue
        seen.add(cls)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    for c in classes:
        # Skip if c is already a subclass of any class in minimal
        if not any(issubclass(c, m) for m in minimal):
            minimal.append(c)
    return minimal

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
        """Return attribute names and descriptions defined by interface."""
        mapping = {}
        # Determine which classes to inspect: this class or the whole MRO
        classes = self.__class__.__mro__ if all else (self.__class__,)
        for cls in classes:
            for name, member in vars(cls).items():
                # Skip private, protected, and magic names
                if name.startswith('_'):
                    continue
                # Skip callables (methods, functions, etc.)
                if callable(member):
                    continue
                # Only add if not already added (derived classes override base)
                if name not in mapping:
                    # Try to get a docstring; for property objects this is their __doc__
                    doc = getattr(member, "__doc__", None)
                    if doc is None:
                        doc = ""
                    mapping[name] = doc
        return mapping

