def names(self, all=False):
        """Return the attribute names defined by the interface."""
        names = []
        seen = set()

        # Helper to add names from a class
        def collect_from(cls):
            for attr in dir(cls):
                if attr.startswith('_'):
                    continue
                if attr in seen:
                    continue
                member = getattr(cls, attr)
                # Exclude methods and other callables
                if callable(member):
                    continue
                seen.add(attr)
                names.append(attr)

        # Collect names from the class itself
        collect_from(self.__class__)

        if all:
            # Optionally include attributes from base classes
            for base in self.__class__.__mro__[1:]:
                if base is object:
                    continue
                collect_from(base)

        return names

def names(self, all=False):
    """Return the attribute names defined by the interface."""
    # Class-level attributes that are part of the interface (non-callable, public)
    iface_attrs = [
        name
        for name, value in vars(self.__class__).items()
        if not name.startswith('_') and not callable(value)
    ]

    # Instance-level attributes that may extend the interface
    inst_attrs = [
        name for name in vars(self).keys() if not name.startswith('_')
    ]

    if all:
        # Include both interface and instance attributes
        return sorted(set(iface_attrs) | set(inst_attrs))
    return sorted(iface_attrs)

