    names = []
    for cls in type(self).__mro__:
        if cls is object:
            continue
        for name, value in cls.__dict__.items():
            if callable(value):
                continue  # skip methods
            if not all and name.startswith('_'):
                continue  # skip private names unless requested
            if name not in names:
                names.append(name)
    return names

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Treat strings/binary data as atomic values, not as iterables.
    if isinstance(sequence, (str, bytes)):
        output.append(sequence)
    # If we have a container, recurse into each element.
    elif isinstance(sequence, (list, tuple, set)):
        for item in sequence:
            _normalizeargs(item, output)
    # Anything else is considered a single interface / declaration.
    else:
        output.append(sequence)

    return output

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    if sequence is None:
        return output
    for arg in sequence:
        # Detect Declarion type if defined; otherwise treat as other
        if hasattr(arg, "__class__"):
            # If it's a Declarion instance – keep as is
            try:
                # Some Declarion classes may define an attribute `is_declarion`
                if getattr(arg, "is_declarion", False):
                    output.append(arg)
                    continue
            except Exception:
                pass
        # If it's an implements spec: e.g., ('implements', klass) keep as is
        if isinstance(arg, (list, tuple)):
            if len(arg) >= 2 and isinstance(arg[0], str) and arg[0] == "implements":
                output.append(arg)
                continue
            # Not an implements spec – flatten recursively
            _normalizeargs(arg, output)
        else:
            # Skip None values
            if arg is not None:
                output.append(arg)
    return output

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Helper to determine if a value should be further expanded.
    # Assume that interfaces (and implement specs) are not iterables
    # unless they are explicitly tuples/lists of other items.
    def _should_expand(obj):
        # Empty string and bytes should not be expanded
        if isinstance(obj, (str, bytes)):
            return False
        # Treat dicts/lists/tuples as iterable containers that need expansion
        if isinstance(obj, (list, tuple, set, frozenset)):
            return True
        # For any other object we consider it an individual interface
        return False

    if _should_expand(sequence):
        for item in sequence:
            _normalizeargs(item, output)
    else:
        output.append(sequence)

    return output

