def to_csv(self, separator=",", header=None):
        """
        Convert graph's points to CSV.
        @param separator: str: delimiter for values, default=','.
        @param header: str or None: optional header string, added as first line.
        @return str: CSV formatted string.
        """
        # Build output lines list
        lines = []
        if header is not None:
            lines.append(header)

        # Iterate over graph points
        for point in getattr(self, "points", []):
            # Try to extract coordinate and value(s)
            coord = None
            val = None

            # If point has direct attributes
            if hasattr(point, "coordinate") and hasattr(point, "value"):
                coord = point.coordinate
                val = point.value
            # Fallback: point may be a tuple of (coordinate, value)
            elif isinstance(point, (list, tuple)) and len(point) >= 2:
                coord, val = point[0], point[1]
            else:
                # Skip points that cannot be interpreted
                continue

            # Ensure coordinate is iterable
            if not isinstance(coord, (list, tuple)):
                coord = (coord,)

            # Build coordinate part
            coord_part = separator.join(map(str, coord))

            # Build value part
            if isinstance(val, (list, tuple)):
                val_part = separator.join(map(str, val))
            else:
                val_part = str(val)

            # Combine coordinate and value parts
            line = coord_part
            if val_part != "":
                line += separator + val_part
            lines.append(line)

        # Join all lines with newline
        return "\n".join(lines)

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional, for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    output_lines = []

    # Add header line if provided
    if header is not None:
        output_lines.append(str(header))

    # Try to get point iterator
    try:
        point_iter = self.points()
    except AttributeError:
        point_iter = iter(self)

    for item in point_iter:
        # Expect item to be a tuple (coord, value) or other iterable of two elements
        try:
            coord, value = item
        except Exception:
            # If not unpackable, skip this item
            continue

        # Prepare coordinate parts
        if isinstance(coord, (list, tuple)) and not isinstance(coord, (str, bytes)):
            coord_parts = [str(c) for c in coord]
        else:
            coord_parts = [str(coord)]

        # Prepare value parts
        if isinstance(value, (list, tuple)) and not isinstance(value, (str, bytes)):
            value_parts = [str(v) for v in value]
        else:
            value_parts = [str(value)]

        # Combine and join with separator
        line = separator.join(coord_parts + value_parts)
        output_lines.append(line)

    # Join all lines with newline characters
    return "\n".join(output_lines) + ("\n" if output_lines else "")

def to_csv(self, separator=",", header=None):
        """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
              Iterables are converted to tables.

        Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.

        To convert :class:`Graph` to CSV inside a Lena sequence,
        use :class:`lena.output.ToCSV`.
        """
        lines = []

        # Add header if provided
        if header is not None:
            # Ensure header does not already end with a newline
            lines.append(header.rstrip("\n"))

        for point in self:
            # Extract coordinate (may be named attribute or first tuple element)
            if hasattr(point, "coordinate"):
                coord = getattr(point, "coordinate")
            elif hasattr(point, "x"):
                coord = getattr(point, "x")
            else:
                # Try to treat point as tuple/list: first element is coordinate
                try:
                    coord = point[0]
                except Exception:
                    coord = point

            # Convert coordinate to string(s) joined by separator
            if isinstance(coord, (list, tuple)):
                coord_parts = [str(c) for c in coord]
                coord_str = separator.join(coord_parts)
            else:
                coord_str = str(coord)

            # Extract value (may be named attribute or second tuple element)
            if hasattr(point, "value"):
                val = getattr(point, "value")
            else:
                try:
                    val = point[1]
                except Exception:
                    val = point

            # Convert value to string(s) joined by separator
            if isinstance(val, (list, tuple)):
                val_parts = [str(v) for v in val]
                val_str = separator.join(val_parts)
            else:
                val_str = str(val)

            # Combine coordinate and value parts
            row = coord_str + separator + val_str
            lines.append(row)

        # Join all lines with newline characters
        return "\n".join(lines)

