                index_value = getattr(err_obj, 'index', None)
            except Exception:
                index_value = None

            # Append the index information to the context's error dictionary,
            # preserving any existing entries
            context['error'].setdefault(error_key, {})
            context['error'][error_key]['index'] = index_value

        # Note: We deliberately do not alter context['value'] or any
        # subcontexts to preserve existing data.

