        # Helper to convert error field name to context key
        def _error_key(field_name):
            # field_name e.g. 'error_E_low' -> suffix 'E_low'
            suffix = field_name[len("error_") :]
            parts = suffix.split("_", 1)
            if not parts:
                return None
            coord = parts[0].lower()
