def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Generate a default observer schema dictionary from a Kubernetes resource dictionary.

    All non-list and non-dict values are replaced with ``None``. For a top-level dictionary
    (when ``first_level`` is ``True``) the values of the identifying fields
    ``apiVersion``, ``kind`` and ``metadata`` are preserved.

    Args:
        manifest_dict (dict): Partial Kubernetes resources.
        first_level (bool, optional): If ``True``, indicates that this dictionary
            represents the complete observer schema for a Kubernetes resource.

    Returns:
        dict: A new dictionary containing the same keys as ``manifest_dict`` but with
        non-structured values replaced by ``None`` (except for the identifying fields
        when ``first_level`` is ``True``).
    """
    identify_keys = {"apiVersion", "kind", "metadata"}
    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recurse into nested dictionaries
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Process each element; preserve dicts, replace others with None
            processed_list = []
            for item in value:
                if isinstance(item, dict):
                    processed_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    processed_list.append(None)
            result[key] = processed_list
        else:
            # Primitive value: keep if identifying field on first level, otherwise None
            result[key] = value if first_level and key in identify_keys else None
    return result

