            "kind": getattr(resource, "kind"),
            "metadata": {
                "name": getattr(getattr(resource, "metadata", {}), "name") or getattr(resource, "name"),
                "namespace": getattr(getattr(resource, "metadata", {}), "namespace") or getattr(resource, "namespace", "default"),
            },
        }

        # Attach the default schema to the resource
        setattr(resource, "observer_schema", default_schema)

