def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os, hashlib, json
    # Helper for checksum
    def _checksum(p):
        h = hashlib.sha256()
        with open(p, "rb") as f:
            for chunk in iter(lambda: f.read(8192), b""):
                h.update(chunk)
        return h.hexdigest()

    # If path is a pyfs root, we assume it behaves like a path string for simplicity.
    if not isinstance(path, str):
        try:
            path = str(path)
        except Exception:
            return False

    if not os.path.isdir(path):
        return False

    ocfl_dir = os.path.join(path, ".ocfl")
    if not os.path.isdir(ocfl_dir):
        return False

    # Validate presence of required files
    ocfl_version = os.path.join(ocfl_dir, "ocfl_version")
    if not os.path.isfile(ocfl_version):
        return False

    manifest_dir = os.path.join(ocfl_dir, "manifest")
    if not os.path.isdir(manifest_dir):
        return False

    latest_manifest_path = os.path.join(manifest_dir, "latest")
    if not os.path.isfile(latest_manifest_path):
        return False

    # Load the latest manifest (expect a JSON mapping of relative paths to SHA256 hashes).
    try:
        with open(latest_manifest_path, "rt", encoding="utf-8") as f:
            manifest_data = json.load(f)
    except Exception:
        # If the manifest cannot be parsed, consider the object invalid.
        return False

    if not isinstance(manifest_data, dict):
        return False

    # Inspect each entry in the manifest. The spec may vary, but we'll handle a direct mapping
    # and a nested structure with a 'data' key.
    objects_mapping = manifest_data
    if "data" in manifest_data and isinstance(manifest_data["data"], dict):
        objects_mapping = manifest_data["data"]

    for rel_path, expected_hash in objects_mapping.items():
        if not isinstance(rel_path, str) or not isinstance(expected_hash, str):
            return False
        full_path = os.path.join(path, rel_path.lstrip("/"))
        if not os.path.isfile(full_path):
            return False
        # Compare calculated hash with expected value
        try:
            calc_hash = _checksum(full_path)
        except Exception:
            return False
        if calc_hash.lower() != expected_hash.lower():
            return False

    # All checks passed; warnings such as deprecated attributes are ignored as per spec.
    return True

