def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary.")

    # Determine spec version
    spec_version = self.spec_version
    if extract_spec_version:
        spec_type = inventory.get("type")
        if spec_type and spec_type in ("v2", "v3"):
            spec_version = spec_type
        else:
            # Fallback to existing spec_version
            spec_version = self.spec_version
    self.spec_version = spec_version

    # Basic structural checks per spec version
    if spec_version == "v2":
        if "metadata" not in inventory:
            raise ValueError("Missing 'metadata' key for spec v2.")
        if "components" not in inventory:
            raise ValueError("Missing 'components' key for spec v2.")
        if not isinstance(inventory["components"], dict):
            raise ValueError("'components' must be a dict for spec v2.")

        # Validate metadata
        metadata = inventory.get("metadata", {})
        if not isinstance(metadata, dict):
            raise ValueError("'metadata' must be a dict.")
        if "name" not in metadata:
            raise ValueError("Metadata must contain a 'name' field.")

        # Validate each component
        for comp_id, comp in inventory["components"].items():
            if not isinstance(comp, dict):
                raise ValueError(f"Component '{comp_id}' must be a dict.")
            if "type" not in comp:
                raise ValueError(f"Component '{comp_id}' missing 'type'.")
    elif spec_version == "v3":
        if "metadata" not in inventory:
            raise ValueError("Missing 'metadata' key for spec v3.")
        if "entities" not in inventory:
            raise ValueError("Missing 'entities' key for spec v3.")
        if not isinstance(inventory["entities"], list):
            raise ValueError("'entities' must be a list for spec v3.")

        # Validate metadata
        metadata = inventory.get("metadata", {})
        if not isinstance(metadata, dict):
            raise ValueError("'metadata' must be a dict.")
        if "name" not in metadata:
            raise ValueError("Metadata must contain a 'name' field.")

        # Validate each entity
        for entity in inventory["entities"]:
            if not isinstance(entity, dict):
                raise ValueError("Each entity must be a dict.")
            if "id" not in entity:
                raise ValueError(f"Entity {entity} missing 'id'.")
            if "type" not in entity:
                raise ValueError(f"Entity {entity} missing 'type'.")
    else:
        raise ValueError(f"Unsupported spec version '{spec_version}'.")

    # If all checks pass, return True for convenience
    return True

