        raise ValueError(f"Unsupported specification version: {spec_version}")

    # Store the parsed inventory and spec_version on the instance
    self.spec_version = spec_version
    self.inventory = inventory

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Ensure inventory is a dictionary-like object
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")

    # Determine the specification version if required
    if extract_spec_version:
        spec_type = inventory.get("type")
        # Only override if the retrieved type is one of the supported values
        if isinstance(spec_type, str) and spec_type in ("NVIDIA", "IBM"):
            self.spec_version = spec_type

    # Validate against the known requirements for each spec_version
    if self.spec_version == "NVIDIA":
        required_keys = ["model", "cores"]
    elif self.spec_version == "IBM":
        required_keys = ["system", "memory"]
    else:
        raise ValueError(f"Unsupported specification version: {self.spec_version}")

    missing_keys = [k for k in required_keys if k not in inventory]
    if missing_keys:
        raise ValueError(f"Inventory is missing required keys for {self.spec_version}: {missing_keys}")

    return True

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.
    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
