def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(digests_used, (set, list, tuple)):
        raise TypeError("digests_used must be a set, list, or tuple")
    needed = set(digests_used)
    found = set()

    for path in manifest_files:
        try:
            with open(path, 'r', encoding='utf-8') as f:
                manifest = json.load(f)
        except Exception as e:
            raise ValueError(f"Could not read manifest '{path}': {e}")

        digests = manifest.get('digests')
        if isinstance(digests, dict):
            found.update(digests.keys())
        elif isinstance(digests, list):
            found.update(digests)

    missing = needed - found
    if missing:
        raise ValueError(f"The following digests are required but missing from manifests: {', '.join(sorted(missing))}")

    unused = found - needed
    if unused and hasattr(self, 'logger'):
        self.logger.warning(f"Digests present in manifest but not required: {', '.join(sorted(unused))}")

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    expected_digests = set()
    for entry in manifest_files:
        if isinstance(entry, dict):
            digest = entry.get('digest')
            if digest:
                expected_digests.add(digest)
        else:
            # In case the entry itself is the digest
            expected_digests.add(entry)
    missing = expected_digests - digests_used
    unused = digests_used - expected_digests
    if missing:
        raise ValueError(f"Missing digests in used set: {', '.join(sorted(missing))}")
    if unused:
        raise ValueError(f"Unused digests in used set: {', '.join(sorted(unused))}")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type check
    if not isinstance(prior, type(self)):
        raise TypeError(f"Prior must be an instance of {type(self).__name__}")

    # Attempt to retrieve dictionary-like representation of the inventories.
    # Supports common attribute names: `inventory`, `data`, `items`, or direct dict.
    def _inventory_dict(v):
        inv = getattr(v, "inventory", None) or v
        for name in ("data", "items", "dict"):
            if hasattr(inv, name):
                d = getattr(inv, name)
                if isinstance(d, dict):
                    return d
        if isinstance(inv, dict):
            return inv
        raise AttributeError("Cannot locate dictionary-like inventory structure")

    self_dict = _inventory_dict(self)
    prior_dict = _inventory_dict(prior)

    # Check that every key in the current inventory exists in the prior inventory.
    for key in self_dict:
        if key not in prior_dict:
            raise ValueError(f"Prior inventory missing key {key}")

    # Optionally, if the stored objects have a `version` attribute, ensure that the prior version is strictly older.
    for key, current_val in self_dict.items():
        prior_val = prior_dict[key]
        if hasattr(current_val, "version") and hasattr(prior_val, "version"):
            if prior_val.version >= current_val.version:
                raise ValueError(
                    f"Prior version of key {key} "
                    f"({prior_val.version}) is not older than current ({current_val.version})"
                )

def validate_as_prior_version(self, prior):
    """Verify that *prior* is a valid preceding version of this inventory.

    The method performs several consistency checks:
    * ``prior`` must be an instance of the same validator class.
    * Both validators must expose a ``version`` attribute, and this validator's
      ``version`` must be exactly one greater than ``prior.version``.
    * Each inventory is expected to have an ``items`` attribute – an iterable
      of objects that possess a unique ``id`` attribute.
    * All items that existed in ``prior`` must still exist in the current
      inventory (i.e. ``prior``'s item identifiers must be a subset of the
      current identifiers).
    * Duplicate identifiers within a single inventory raise an error.
    * For any item that existed in both inventories, the category field must
      match – any other differences are considered permissible (e.g. quantity).

    If any of the above conditions fail a :class:`ValueError` is raised with
    a description of the issue.  Successful validation returns ``None``.
    """
    # 1. Ensure *prior* is the same type
    if not isinstance(prior, type(self)):
        raise TypeError(f"'prior' must be an instance of {type(self).__name__}")

    # 2. Check that both inventories expose a `version` attribute
    if not hasattr(self, "version") or not hasattr(prior, "version"):
        raise AttributeError(
            "Both the current and prior validator must provide a 'version' attribute."
        )
    if self.version != prior.version + 1:
        raise ValueError(
            f"Current inventory version ({self.version}) must be exactly "
            f"one greater than prior version ({prior.version})."
        )

    # 3. Ensure both inventories expose an iterable of items with unique `id`s
    for inventory, name in [(self, "current"), (prior, "prior")]:
        if not hasattr(inventory, "items"):
            raise AttributeError(
                f"The {name} inventory must provide an 'items' iterable."
            )
        # Mirror to treat any iterable (list/tuple/set/generator)
        try:
            # Convert to list to allow repeated traversal
            inventory._items_list = list(inventory.items)
        except Exception as exc:
            raise TypeError(
                f"Could not iterate over 'items' in the {name} inventory: {exc}"
            ) from exc
        # Check each item has an 'id' attribute
        for item in inventory._items_list:
            if not hasattr(item, "id"):
                raise AttributeError(
                    f"An item in the {name} inventory lacks an 'id' attribute."
                )
        # Verify uniqueness of identifiers
        ids = [item.id for item in inventory._items_list]
        if len(ids) != len(set(ids)):
            raise ValueError(
                f"Duplicate item ids found in the {name} inventory."
            )

    # 4. Current inventory must contain at least all items from prior
    prior_ids = {item.id for item in prior._items_list}
    current_ids = {item.id for item in self._items_list}
    missing = prior_ids - current_ids
    if missing:
        raise ValueError(
            f"The current inventory is missing items from prior: {sorted(missing)}"
        )

    # 5. For common items, verify certain attributes remain unchanged
    #    (Here we check `category`; other fields are ignored)
    id_to_current_item = {item.id: item for item in self._items_list}
    for prior_item in prior._items_list:
        current_item = id_to_current_item.get(prior_item.id)
        if current_item is None:
            continue  # already caught missing in step 4
        # Compare categories if present on both objects
        prior_cat = getattr(prior_item, "category", None)
        current_cat = getattr(current_item, "category", None)
        if prior_cat is not None and current_cat is not None and prior_cat != current_cat:
            raise ValueError(
                f"Item {prior_item.id} changed category from {prior_cat!r} "
                f"to {current_cat!r}"
            )

    # 6. All checks passed – validation succeeded
    return None

def validate_as_prior_version(self, prior):
    """
    Check that ``prior`` is a valid previous version of the current inventory.
    ``prior`` must be an InventoryValidator instance, and the current
    inventory must have a newer version, later timestamp and larger id than
    ``prior``.  Raises a ``ValueError`` if any of these conditions are not
    met.
    """
    # Ensure the argument is an InventoryValidator or derived type.
    if not isinstance(prior, type(self)):
        raise TypeError(f"Expected an InventoryValidator, got {type(prior).__name__}")

    # Helper to fetch common attributes with graceful fall‑backs.
    def _ get_attr(obj, *names):
        for name in names:
            if isinstance(obj, dict):
                if name in obj:
                    return obj[name]
            else:
                if hasattr(obj, name):
                    return getattr(obj, name)
        return None

    current_version = _get_attr(self.inventory, "version", "generation", "ver")
    prior_version = _get_attr(prior.inventory, "version", "generation", "ver")
    if current_version is None or prior_version is None:
        raise ValueError("Both inventories must expose a numerical version or generation")

    if int(current_version) <= int(prior_version):
        raise ValueError(f"Current inventory version ({current_version}) "
                         f"must be greater than prior inventory version ({prior_version})")

    current_id = _get_attr(self.inventory, "inventory_id", "id", "uuid")
    prior_id = _get_attr(prior.inventory, "inventory_id", "id", "uuid")
    if current_id is None or prior_id is None:
        raise ValueError("Both inventories must expose an id/inventory_id")
    if str(current_id) <= str(prior_id):
        raise ValueError(f"Current inventory id ({current_id}) must be greater than prior inventory id ({prior_id})")

    current_ts = _get_attr(self.inventory, "timestamp", "time", "created_at")
    prior_ts = _get_attr(prior.inventory, "timestamp", "time", "created_at")
    if current_ts is None or prior_ts is None:
        raise ValueError("Both inventories must expose a timestamp")
    try:
        # Try parsing as a datetime if necessary
        from datetime import datetime
        if isinstance(current_ts, str):
            current_ts = datetime.fromisoformat(current_ts)
        if isinstance(prior_ts, str):
            prior_ts = datetime.fromisoformat(prior_ts)
    except Exception:
        pass  # leave as is; natural ordering may still work
    if current_ts <= prior_ts:
        raise ValueError(f"Current inventory timestamp ({current_ts}) must be later than prior inventory timestamp ({prior_ts})")

    return True

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Build the base mapping from the target version
    mapping = {}
    # Handle the possibility that inventory may be a dict of {version: entries}
    entries = inventory.get(version, [])
    for entry in entries:
        logical_path = entry.get("logical_path")
        content_file = entry.get("content_file")
        if logical_path is not None and content_file is not None:
            mapping.setdefault(logical_path, set()).add(content_file)

    # If mapping is empty or no later versions exist, return immediately
    if not mapping:
        return mapping

    # Determine which entries in later versions may reference the same logical paths
    for ver_key, other_entries in inventory.items():
        # Skip the target version itself
        if ver_key == version:
            continue
        # Skip non-numeric version keys; otherwise try numeric comparison
        try:
            if isinstance(ver_key, str):
                # Attempt to convert to int; if fails, skip this key
                if int(ver_key) <= int(version):
                    continue
            else:
                if ver_key <= version:
                    continue
        except (ValueError, TypeError):
            # If comparison fails, skip this key
            continue

        for entry in other_entries:
            logical_path = entry.get("logical_path")
            content_file = entry.get("content_file")
            # Only consider logical paths already present in the target version
            if logical_path in mapping and content_file is not None:
                mapping[logical_path].add(content_file)

    return mapping

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result = {}
    # Iterate over all versions in the inventory that are <= the requested version
    for ver_key, state in inventory.items():
        # Try to interpret the version key as an integer for comparison
        try:
            ver_num = int(ver_key)
        except Exception:
            ver_num = ver_key
        if ver_num > version:
            continue
        # Merge the logical path mappings from this state into the result
        for logical_path, files in state.items():
            # Ensure we work with a set of files
            files_set = set(files)
            result.setdefault(logical_path, set()).update(files_set)
    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Attempt to parse a common inventory layout: {version: {logical_path: set(files)}}
    if isinstance(inventory, dict) and any(isinstance(v, dict) for v in inventory.values()):
        try:
            mapping = inventory[version]
            # Return a copy to avoid accidental mutation of the inventory's internal data
            return {lp: set(files) for lp, files in mapping.items()}
        except (KeyError, TypeError):
            # Fall back to other interpretation below
            pass

    # Fallback interpretation: inventory is {logical_path: {version: set(files)}}
    result = {}
    for logical_path, ver_map in inventory.items():
        if isinstance(ver_map, dict):
            files = ver_map.get(version)
            if files is not None:
                result[logical_path] = set(files)
    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_map = {}

    # Handle inventory as a dict mapping logical_path -> list of entries
    if isinstance(inventory, dict):
        for logical_path, entries in inventory.items():
            for entry in entries:
                # Entry might be a tuple (file_path, ver) or a dict
                if isinstance(entry, (list, tuple)):
                    file_path, ver = entry[0], entry[1]
                elif isinstance(entry, dict):
                    file_path = entry.get("file")
                    ver = entry.get("version")
                else:
                    continue

                if ver is not None and ver <= version:
                    logical_map.setdefault(logical_path, set()).add(file_path)
    else:
        # Assume inventory is an iterable of entry dicts
        for entry in inventory:
            if not isinstance(entry, dict):
                continue
            logical_path = entry.get("logical_path")
            file_path = entry.get("file")
            ver = entry.get("version")
            if logical_path and file_path and ver is not None and ver <= version:
                logical_map.setdefault(logical_path, set()).add(file_path)

    return logical_map

def validate_fixity(self, fixity, manifest_files):
        """
        Validate a fixity block in the inventory.

        Checks that:
        * ``fixity`` is a mapping
        * It contains a top‑level ``checksum`` and a sequence of ``files`` entries
          (each entry must be a mapping containing at least a ``filename`` key)
        * Every ``filename`` mentioned in the fixity block is present in
          ``manifest_files``.
        """
        # Basic type checks
        if not isinstance(fixity, dict):
            raise TypeError("fixity must be a dictionary")

        # Ensure required top‑level keys exist
        required_keys = {"checksum", "files"}
        missing_keys = required_keys - set(fixity.keys())
        if missing_keys:
            raise ValueError(f"Missing required key(s) in fixity block: {missing_keys}")

        if not isinstance(fixity["checksum"], str):
            raise TypeError("The key 'checksum' must be a string")

        files_seq = fixity["files"]
        if not isinstance(files_seq, (list, tuple)):
            raise TypeError("The key 'files' must contain a list or tuple of entries")

        # Prepare a set for quick membership testing
        manifest_set = set(manifest_files)

        for idx, entry in enumerate(files_seq):
            if not isinstance(entry, dict):
                raise TypeError(f"Entry {idx} in fixity['files'] must be a dict")

            # Each entry must include the filename
            if "filename" not in entry:
                raise ValueError(f"Entry {idx} missing 'filename' key")

            filename = entry["filename"]
            if not isinstance(filename, str):
                raise TypeError(f"'filename' in entry {idx} must be a string")

            if filename not in manifest_set:
                raise ValueError(
                    f"File referenced in fixity block not present in manifest: {filename}"
                )

            # Optionally verify that the checksum field exists and is a string
            if "checksum" not in entry:
                raise ValueError(f"Entry {idx} missing 'checksum' key")
            if not isinstance(entry["checksum"], str):
                raise TypeError(f"The 'checksum' value in entry {idx} must be a string")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")
    for file_name, checksums in fixity.items():
        if file_name not in manifest_files:
            raise ValueError(f"File '{file_name}' in fixity block not found in manifest.")
        if not isinstance(checksums, dict):
            raise ValueError(f"Fixity entry for file '{file_name}' must be a dictionary.")
        if not checksums:
            raise ValueError(f"No checksums provided for file '{file_name}'.")
        for algo, value in checksums.items():
            if not isinstance(algo, str):
                raise ValueError(f"Checksum algorithm key for file '{file_name}' must be a string.")
            if not isinstance(value, str):
                raise ValueError(f"Checksum value for algorithm '{algo}' on file '{file_name}' must be a string.")
            if not value:
                raise ValueError(f"Checksum value for algorithm '{algo}' on file '{file_name}' is empty.")
    return True

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        errors = []

        if not isinstance(fixity, dict):
            errors.append("Fixity block must be a dictionary.")
            raise ValueError(" ; ".join(errors))

        manifest_set = set(manifest_files)

        for file_name, checksums in fixity.items():
            if file_name not in manifest_set:
                errors.append(f"File '{file_name}' in fixity not present in manifest.")
            if not isinstance(checksums, dict) or not checksums:
                errors.append(f"Checksums for '{file_name}' must be a non-empty dictionary.")
                continue

            from string import hexdigits
            for algorithm, checksum in checksums.items():
                if not isinstance(checksum, str) or not checksum:
                    errors.append(f"Checksum for '{file_name}' (algorithm: {algorithm}) must be a non-empty string.")
                elif not all(c in hexdigits for c in checksum.strip()):
                    errors.append(f"Checksum for '{file_name}' (algorithm: {algorithm}) contains non-hex characters.")

        for manifest_file in manifest_set:
            if manifest_file not in fixity:
                errors.append(f"File '{manifest_file}' from manifest not represented in fixity block.")

        if errors:
            raise ValueError("Fixity validation error(s): " + "; ".join(errors))

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
