        manifest_set = set(manifest_files)

        for file_id, entry in fixity.items():
            # Ensure the file_id is present in the manifest
            if file_id not in manifest_set:
                raise ValueError(f"Fixity entry references unknown file ID: {file_id}")

            # Each entry should be a dictionary with at least 'hash' and 'hash_algorithm'
            if not isinstance(entry, dict):
                raise ValueError(f"Fixity entry for file ID {file_id} must be a dict, got {type(entry).__name__}")

            # Verify required keys
            required_keys = {"hash", "hash_algorithm"}
            missing = required_keys - entry.keys()
            if missing:
                raise ValueError(f"Fixity entry for file ID {file_id} is missing keys: {', '.join(missing)}")

            # Basic type validation for the hash information
            if not isinstance(entry["hash"], str):
                raise ValueError(f"Hash value for file ID {file_id} must be a string")
            if not isinstance(entry["hash_algorithm"], str):
