        # If all checks pass, simply return None (or you could return a bool)
        return None

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Ensure we have a place to collect errors
        if not hasattr(self, 'errors'):
            self.errors = []

        if not isinstance(fixity, dict):
            self.errors.append("The 'fixity' block must be a dictionary.")
            return

        # Ensure manifest_files is a set for fast membership testing
        if not isinstance(manifest_files, (set, list, tuple)):
            self.errors.append("The 'manifest_files' argument must be an iterable of file IDs.")
            return
        manifest_set = set(manifest_files)

        for file_id, entry in fixity.items():
            # Basic type checks
            if not isinstance(file_id, str):
                self.errors.append(f"File ID '{file_id}' is not a string.")
                continue
            if not isinstance(entry, dict):
                self.errors.append(f"Fixity entry for file ID '{file_id}' must be a dictionary.")
                continue

            # Check that the file is listed in the manifest
            if file_id not in manifest_set:
                self.errors.append(f"File ID '{file_id}' referenced in fixity block is not present in the manifest.")
                continue

            # Verify required keys
            checksum_type = entry.get('checksum_type')
            checksum_value = entry.get('checksum')
            if checksum_type is None or checksum_value is None:
                self.errors.append(
                    f"Fixity entry for file ID '{file_id}' is missing 'checksum_type' or 'checksum' keys."
                )
                continue

            # Basic validation of checksum type
            if checksum_type.lower() not in ('md5', 'sha1', 'sha256'):
                self.errors.append(
                    f"Unsupported checksum type '{checksum_type}' for file ID '{file_id}'. "
                    "Supported types are md5, sha1, and sha256."
                )

            # Basic validation of checksum value
            if not isinstance(checksum_value, str) or not checksum_value:
                self.errors.append(
                    f"The 'checksum' value for file ID '{file_id}' must be a non‑empty string."
                )
            else:
                # Optionally, check that the checksum length matches the algorithm
                expected_lengths = {'md5': 32, 'sha1': 40, 'sha256': 64}
                if len(checksum_value) != expected_lengths.get(checksum_type.lower(), 0):
                    self.errors.append(
                        f"The 'checksum' value for file ID '{file_id}' does not match "
                        f"the expected length for {checksum_type} (got {len(checksum_value)} characters)."
                    )

def files_list(path):
