    temp = {}
    for root, _, files in os.walk(folder):
        for f in files:
            if f.startswith('.'):
                continue  # Skip hidden files
            base, _ = os.path.splitext(f)
            full_path = os.path.join(root, f)
            temp.setdefault(base, []).append(full_path)

    # Keep only groups that contain an XML file and structure the output
    result = {}
    for base, paths in temp.items():
        xml_path = None
        other_paths = []
        for p in paths:
            if p.lower().endswith('.xml'):
                xml_path = p
            else:
                other_paths.append(p)
        if xml_path:
