    ----------
    pieces : dict | list | tuple | iterable
        The components of a version.  If a mapping is supplied it may contain
        the keys ``'major'``, ``'minor'``, ``'patch'``, ``'prerelease'`` (or
        ``'pre'``) and ``'build'``.  If an iterable of values is supplied the
        order is assumed to be the same as the ``semver`` representation
        (major, minor, patch, prerelease, build).

    style : str or callable
        Determines how the version is rendered.  Supported string styles:

        * ``'semver'``   – a standard semantic‑version string, e.g.
                           ``"1.2.3-beta+001"``
        * ``'array'``    – a list ``[major, minor, patch, prerelease, build]``
        * ``'tuple'``    – a tuple ``(major, minor, patch, prerelease, build)``
        * ``'dict'``     – the original mapping
        * ``'string'``   – a dot‑separated string of the numeric parts
                           followed by any prerelease/build parts separated
                           by dots (default)
        * ``'list'``     – a list copy of the iterable
        * ``'join'``     – join all elements with a period

        If ``style`` is callable it will be called with the ``pieces`` value
        and its return value will be used.

    Returns
    -------
    str | list | tuple | dict
        The rendered version representation.
    """
    # Normalise `style` to a callable if an explicit callable is provided
    if callable(style) and not isinstance(style, str):
        return style(pieces)

    # Default to the common string representation
    if not style:
        style = 'string'

    # Handle mapping input
    if isinstance(pieces, dict):
        # Extract known parts
        major   = pieces.get('major', 0)
        minor   = pieces.get('minor', 0)
        patch   = pieces.get('patch', 0)
        pre     = pieces.get('prerelease') or pieces.get('pre')
        build   = pieces.get('build')

        if style == 'semver':
            ver = f"{major}.{minor}.{patch}"
            if pre:
                ver += f"-{pre}"
            if build:
                ver += f"+{build}"
            return ver

        if style == 'array':
            return [major, minor, patch, pre, build]

        if style == 'tuple':
            return (major, minor, patch, pre, build)

        if style == 'dict':
            return pieces

        # 'string' or default
        parts = [str(major), str(minor), str(patch)]
        if pre:
            parts.append(pre)
        if build:
            parts.append(build)
        return '.'.join(parts)

    # Handle iterable input (list, tuple, set, etc.)
    if hasattr(pieces, '__iter__') and not isinstance(pieces, (str, bytes)):
        # Convert to list first for easier manipulation
        seq = list(pieces)

        if style == 'list':
            return list(seq)

        if style == 'tuple':
            return tuple(seq)

        if style == 'join':
            return '.'.join(map(str, seq))

        # Default to joined string representation
        return ''.join(map(str, seq))

    # Fallback: return the string representation of a single value
    return str(pieces)

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Helper: safely get element or None
    def get(index):
        return pieces[index] if index < len(pieces) else None

    if style == "semver":
        major = get(0)
        minor = get(1)
        patch = get(2)
        pre = get(3)
        build = get(4)
        if major is None or minor is None or patch is None:
            raise ValueError("SEMVER requires at least major, minor, and patch")
        version = f"{major}.{minor}.{patch}"
        if pre:
            version += f"-{pre}"
        if build:
            version += f"+{build}"
        return version

    elif style == "pep440":
        major = get(0)
        minor = get(1)
        patch = get(2)
        pre = get(3)
        post = get(4)
        dev = get(5)
        build = get(6)
        if major is None or minor is None:
            raise ValueError("PEP440 requires at least major and minor")
        parts = [f"{major}", f"{minor}"]
        if patch is not None:
            parts.append(str(patch))
        version = ".".join(parts)
        if pre:
            version += f".rc{pre}"
        if post:
            version += f".post{post}"
        if dev:
            version += f".dev{dev}"
        if build:
            version += f"+{build}"
        return version

    elif style == "calver":
        year = get(0)
        month = get(1)
        day = get(2)
        build = get(3)
        if year is None or month is None or day is None:
            raise ValueError("CALVER requires at least year, month, and day")
        version = f"{year}.{month}.{day}"
        if build:
            version += f"+{build}"
        return version

    else:
        raise ValueError(f"Unsupported style: {style}")

def plus_or_dot(pieces):
    """Return a '+' if none of the pieces contain a plus sign, otherwise return a '.'."""
    if pieces is None:
        return '+'
    for piece in pieces:
        if '+' in piece:
            return '.'
    return '+'

