    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import os, hashlib
    num_objects = 0
    good_objects = 0
    warnings = []
    root = getattr(self, 'storage_root', None)
    if root is None:
        raise ValueError('storage_root attribute not defined')
    for dirpath, dirnames, filenames in os.walk(root):
        for fname in filenames:
            full_path = os.path.join(dirpath, fname)
            rel_path = os.path.relpath(full_path, root)
            num_objects += 1
            is_valid = True
            # Fetch metadata if available
            obj_meta = getattr(self, 'objects', {}).get(rel_path)
            # Validate object existence and metadata
            if validate_objects:
                if obj_meta is None:
                    is_valid = False
                    warnings.append(f'Object metadata missing for {rel_path}')
                else:
                    # Check file size matches metadata
                    try:
                        size = os.path.getsize(full_path)
                        if obj_meta.get('size') != size:
                            is_valid = False
                            warnings.append(f'Size mismatch for {rel_path}: expected {obj_meta.get("size")} got {size}')
                    except Exception as exc:
                        is_valid = False
                        warnings.append(f'Failed to get size for {rel_path}: {exc}')
            # Validate digests
            if check_digests:
                if obj_meta is None:
                    if is_valid:
                        is_valid = False
                        warnings.append(f'Cannot verify digest without metadata for {rel_path}')
                else:
                    stored_digest = obj_meta.get('digest')
                    if stored_digest is None:
                        if is_valid:
                            is_valid = False
                            warnings.append(f'No stored digest for {rel_path}')
                    else:
                        try:
                            hasher = hashlib.sha256()
                            with open(full_path, 'rb') as fp:
                                for chunk in iter(lambda: fp.read(8192), b''):
                                    hasher.update(chunk)
                            actual_digest = hasher.hexdigest()
                            if actual_digest != stored_digest:
                                is_valid = False
                                warnings.append(f'Digest mismatch for {rel_path}: expected {stored_digest} got {actual_digest}')
                        except Exception as exc:
                            if is_valid:
                                is_valid = False
                                warnings.append(f'Error computing digest for {rel_path}: {exc}')
            if is_valid:
                good_objects += 1
    if show_warnings:
        for msg in warnings:
            print(msg)
    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        (num_objects, good_objects) - tuple with number of objects checked
        and number of objects checked that were found to be valid.
    """
    num_objects = 0
    good_objects = 0
    for obj in getattr(self, 'objects', []):
        num_objects += 1
        is_valid = True
        if validate_objects:
            try:
                # Assume each object has a validate() method returning True/False
                is_valid = bool(obj.validate())
            except Exception as e:
                is_valid = False
                if show_warnings:
                    print(f"Validation error for {obj!r}: {e}")
        if check_digests:
            try:
                # Assume each object has digest attributes to compare
                if getattr(obj, 'digest', None) != getattr(obj, 'stored_digest', None):
                    is_valid = False
                    if show_warnings:
                        print(f"Digest mismatch for {obj!r}")
            except Exception as e:
                is_valid = False
                if show_warnings:
                    print(f"Digest check error for {obj!r}: {e}")
        if is_valid:
            good_objects += 1
    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        (num_objects, good_objects) – number of objects examined and number that passed validation
    """
    import hashlib

    num_objects = 0
    good_objects = 0

    # Expect the storage to be a mapping of identifiers to object metadata.
    storage = getattr(self, "storage", {})
    for key, item in storage.items():
        num_objects += 1
        valid = True

        # Optional object‑level validation if a validate method is provided.
        if validate_objects:
            validate_fn = getattr(item, "validate", None)
            if callable(validate_fn):
                try:
                    valid = bool(validate_fn())
                except Exception:
                    valid = False
            else:
                # Default: consider the object valid if it has a non‑empty content field.
                if "content" not in item or not item["content"]:
                    valid = False

        # Check the stored digest against a freshly computed one.
        if valid and check_digests:
            content = item.get("content", b"")
            expected_digest = item.get("digest")
            if expected_digest is not None:
                actual_digest = hashlib.sha256(content).hexdigest()
                if actual_digest != expected_digest:
                    valid = False

        if valid:
            good_objects += 1
        elif show_warnings:
            print(f"Warning: Hierarchy object '{key}' failed validation")

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    warnings = []

    root = getattr(self, 'storage_root', None)
    if not root:
        return 0, 0

    for dirpath, dirnames, filenames in os.walk(root):
        for fname in filenames:
            filepath = os.path.join(dirpath, fname)
            num_objects += 1
            is_valid = True

            if validate_objects:
                # Optional digest check
                if check_digests:
                    try:
                        with open(filepath, 'rb') as f:
                            data = f.read()
                        digest = hashlib.sha256(data).hexdigest()
                        # Assume metadata file has same name with a .meta extension
                        meta_path = filepath + '.meta'
                        if os.path.isfile(meta_path):
                            with open(meta_path, 'r') as mf:
                                expected = mf.read().strip()
                            if digest != expected:
                                is_valid = False
                                warnings.append(
                                    f'Digest mismatch: {filepath} (expected {expected} got {digest})'
                                )
                    except Exception as e:
                        is_valid = False
                        warnings.append(f'Error validating {filepath}: {e}')

            if is_valid:
                good_objects += 1

    if show_warnings and warnings:
        for w in warnings:
            print(w)

    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point. Also keep a record of any content digests
    different from those in the root inventory so that we can also check them when validating the content.
    """
    import os, json

    # Root inventory should already be loaded into self.root_inventory (a dict: file_path -> digest)
    if not hasattr(self, 'root_inventory') or not isinstance(self.root_inventory, dict):
        raise RuntimeError('root_inventory is not defined or not a dict')

    differing_digests = {}          # file_path -> list of (version, ver_digest, root_digest)
    seen_files = set()              # files that have appeared in inventories so far

    for version in version_dirs:
        inv_path = os.path.join(self.base_path, version, 'inventory.json')
        if not os.path.isfile(inv_path):
            raise AssertionError(f'Inventory file missing for version {version!r} at {inv_path!r}')

        try:
            with open(inv_path, 'r', encoding='utf-8') as f:
                version_inventory = json.load(f)
        except Exception as e:
            raise AssertionError(f'Failed to load inventory for version {version!r}: {e}')

        if not isinstance(version_inventory, dict):
            raise AssertionError(f'Inventory for version {version!r} is not a dict')

        # Ensure all entries are known in the root inventory
        for path in version_inventory:
            if path not in self.root_inventory:
                raise AssertionError(
                    f'Inventory for version {version!r} contains unknown file {path!r}'
                )

        # Update the set of seen files
        seen_files.update(version_inventory.keys())

        # Validate that the size of seen_files matches the root inventory up to this point
        # i.e., no file in the root inventory is missing from the cumulative inventories
        if seen_files != set(self.root_inventory.keys()):
            missing = set(self.root_inventory.keys()) - seen_files
            if missing:
                raise AssertionError(
                    f'Inventory for version {version!r} is missing files: {sorted(missing)!r}'
                )
            # If some extra files are present in the root that are not yet added in this version,
            # that's normal; we just need to check digest differences only for files that exist
            pass

        # Compare digests for files present in this version
        for path, root_digest in self.root_inventory.items():
            ver_digest = version_inventory.get(path)
            if ver_digest is None:
                # File not yet introduced in this version – skip comparison
                continue
            if ver_digest != root_digest:
                differing_digests.setdefault(path, []).append(
                    (version, ver_digest, root_digest)
                )

    # Store the differences for later use
    self.differing_digests = differing_digests
    return differing_digests

def validate_version_inventories(self, version_dirs):
    """
    Ensure each version directory contains an inventory that includes all
    files up to that point, and record any digest differences from the
    root inventory so they can be checked later.
    """
    # Path to the root inventory (assumed to live directly under self.root)
    root_inventory_path = os.path.join(self.root, "inventory.json")
    if not os.path.isfile(root_inventory_path):
        raise FileNotFoundError(f"Root inventory not found at {root_inventory_path}")

    # Load the root inventory into a dictionary: {file_path: digest}
    root_inventory = json.load(open(root_inventory_path, "rt", encoding="utf-8"))
    root_map = {entry["path"]: entry["digest"] for entry in root_inventory.get("files", [])}

    # Store differences between version inventories and the root inventory
    self.digests_different = []  # list of tuples (path, version_digest, root_digest)
    seen = {}  # Files seen so far in all previous versions
    errors = []

    for ver_dir in version_dirs:
        # Path to this version's inventory
        version_inventory_path = os.path.join(self.root, ver_dir, "inventory.json")
        if not os.path.isfile(version_inventory_path):
            errors.append(f"Missing inventory file for version directory '{ver_dir}'")
            continue

        # Load inventory
        inv = json.load(open(version_inventory_path, "rt", encoding="utf-8"))
        current_map = {entry["path"]: entry["digest"] for entry in inv.get("files", [])}

        # Check that all files previously seen are still present
        for path, prev_digest in seen.items():
            if path not in current_map:
                errors.append(
                    f"Version '{ver_dir}' missing file '{path}' that was present in earlier version"
                )

        # Record any digest differences relative to the root inventory
        for path, cur_digest in current_map.items():
            if path in root_map and root_map[path] != cur_digest:
                self.digests_different.append((path, cur_digest, root_map[path]))

        # Update the set of seen files for subsequent versions
        seen.update(current_map)

    if errors:
        raise AssertionError("Inventory validation errors:\n" + "\n".join(errors))

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'    - looks like an OCFL Storage Root
        'object'  - looks like an OCFL Object
        'file'    - a regular file (might be an inventory)
        other     - string explaining error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    import re

    if not os.path.exists(path):
        return f"path '{path}' does not exist"

    if os.path.isfile(path):
        return "file"

    # Path is a directory
    try:
        entries = os.listdir(path)
    except OSError as e:
        return f"cannot list directory '{path}': {e}"

    # Detect root: OCFL storage root typically contains a ".ocfl_version" file
    if ".ocfl_version" in entries:
        return "root"

    # Detect object: OCFL object root typically contains "inventory.json"
    if "inventory.json" in entries:
        return "object"

    # Detect object via presence of a version subdirectory matching "0=*"
    # Pattern: a directory name that contains a "0=" file inside it
    # Since we don't know the exact structure, check for subdirs that
    # have a file matching the Namaste pattern "0=*".
    for sub in entries:
        sub_path = os.path.join(path, sub)
        if os.path.isdir(sub_path):
            try:
                sub_entries = os.listdir(sub_path)
            except OSError:
                continue
            for f in sub_entries:
                if re.match(r"^0=.*$", f):
                    # found a namaste file in a subdirectory
                    return "object"

    # Heuristic fallback: if the directory contains any file that looks like a 
    # Namaste file (i.e., starts with "0="), treat it as an object.
    for f in entries:
        if os.path.isfile(os.path.join(path, f)) and re.match(r"^0=.*$", f):
            return "object"

    return f"unidentified structure at '{path}'"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if not bug_ids:
        return
    # Convert bug_ids into a comma-separated string of IDs
    ids_str = ','.join(str(bug_id) for bug_id in bug_ids)
    # If the params already contain an 'ids' key, concatenate the new IDs
    if 'ids' in params:
        existing = params['ids']
        # Handle case where existing is a string or collection
        if isinstance(existing, (list, tuple, set)):
            existing_str = ','.join(str(x) for x in existing)
        else:
            existing_str = str(existing)
        # Merge while preserving uniqueness
        merged_ids = set(filter(None, (existing_str.split(','), ids_str.split(','))))
        params['ids'] = ','.join(merged_ids)
    else:
        params['ids'] = ids_str
    # No explicit return needed – params is modified in place.

def amend_bzparams(self, params, bug_ids):
        """Amend the Bugzilla params"""
        if not isinstance(params, dict):
            raise TypeError("params must be a dict")
        if bug_ids is None:
            return params
        if isinstance(bug_ids, (str, bytes)):
            bug_ids = [bug_ids]
        if not isinstance(bug_ids, (list, tuple)):
            raise TypeError("bug_ids must be an iterable of IDs")
        cleaned_ids = []
        for b in bug_ids:
            try:
                cleaned = int(b)
            except Exception:
                raise ValueError(f"Bug ID {b!r} cannot be converted to an int")
            cleaned_ids.append(str(cleaned))
        params['ids'] = ','.join(cleaned_ids)
        return params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Ensure bug IDs are supplied as a list; the Bugzilla API expects a list
    if bug_ids:
        if isinstance(bug_ids, (list, tuple)):
            params['ids'] = list(bug_ids)
        else:
            # Support a single integer or string ID
            params['ids'] = [bug_ids]
    return params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params.

    Ensures that the supplied ``params`` dictionary contains the key ``ids`` if
    ``bug_ids`` is provided, and guarantees that a standard set of Bugzilla
    fields is requested.  The function returns a new dictionary containing the
    amended parameters and does not mutate the original ``params`` object.
    """
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    amended = params.copy()

    # Insert the list of bug IDs if supplied
    if bug_ids:
        # Convert each ID to an int if possible; bubble up ValueError otherwise
        amended["ids"] = [int(bid) for bid in bug_ids]

    # Ensure a sensible set of include_fields
    standard_fields = {"id", "summary", "status", "resolution", "creation_time"}
    existing = set()
    if "include_fields" in amended:
        existing = {f.strip() for f in amended["include_fields"].split(",") if f.strip()}
        amended["include_fields"] = ",".join(sorted(existing | standard_fields))
    else:
        amended["include_fields"] = ",".join(sorted(standard_fields))

    return amended

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # No change if no bug IDs provided
    if not bug_ids:
        return
    # Normalize current ids already in params
    existing = params.get('ids')
    if existing:
        if isinstance(existing, (list, set, tuple)):
            existing_ids = set(map(str, existing))
        else:
            existing_ids = set(map(str, existing.split(',')))
    else:
        existing_ids = set()
    # Normalize incoming bug_ids
    if isinstance(bug_ids, (list, set, tuple)):
        incoming_ids = set(map(str, bug_ids))
    else:
        # Single ID or comma‑separated string
        if isinstance(bug_ids, str):
            incoming_ids = set(map(str, bug_ids.split(',')))
        else:
            incoming_ids = {str(bug_ids)}
    # Merge, dedupe, and store back (comma separated string for Bugzilla API)
    merged_ids = sorted(existing_ids | incoming_ids)
    params['ids'] = ','.join(merged_ids)

def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, value) pairs, deep merging MappingNode values for duplicate keys.
    The last node's value wins for non-mapping conflicts.
    """

    def _merge_mapping_nodes(node_a, node_b):
        # Merge two MappingNodes recursively, node_b overrides node_a where appropriate.
        dict_a = {key.value: (key, val) for key, val in node_a.value}
        dict_b = {key.value: (key, val) for key, val in node_b.value}

        merged_pairs = []

        # Process keys from node_a preserving their order.
        for key_a, val_a in node_a.value:
            key_str = key_a.value
            if key_str in dict_b:
                val_b = dict_b[key_str][1]
                merged_val = _merge_nodes(val_a, val_b)
                merged_pairs.append((key_a, merged_val))
            else:
                merged_pairs.append((key_a, val_a))

        # Append any new keys from node_b that were not in node_a.
        for key_b, val_b in node_b.value:
            if key_b.value not in dict_a:
                merged_pairs.append((key_b, val_b))

        return type(node_a)(tag=node_a.tag, value=merged_pairs)

    def _merge_nodes(node_a, node_b):
        # Deep merge nodes: if both are MappingNodes, merge them; otherwise return node_b.
        if hasattr(node_a, "tag") and hasattr(node_b, "tag") and node_a.tag == node_b.tag:
            if isinstance(node_a, type(node_b)) and isinstance(node_a, ruamel.yaml.nodes.MappingNode):
                return _merge_mapping_nodes(node_a, node_b)
        return node_b

    merged = {}
    order = []

    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            merged_value = _merge_nodes(merged[key], value_node)
            merged[key] = merged_value
        else:
            merged[key] = value_node
            order.append(key)

    return [(ruamel.yaml.nodes.ScalarNode(tag='tag:yaml.org,2002:str', value=k), merged[k]) for k in order]

def deep_merge_nodes(nodes):
    """
    Merge a list of (key_node, value_node) tuples by key, deep‑merging nested MappingNodes.
    """
    # Stores result tuples and index by key value
    result = []
    key_to_index = {}
    for key_node, val_node in nodes:
        key = getattr(key_node, "value", None)
        if key in key_to_index:
            i = key_to_index[key]
            existing_key, existing_val = result[i]
            # If both values are MappingNodes, merge recursively
            if (
                isinstance(existing_val, MappingNode)
                and isinstance(val_node, MappingNode)
            ):
                merged_children = deep_merge_nodes(
                    existing_val.value + val_node.value
                )
                merged_node = MappingNode(tag=existing_val.tag, value=merged_children)
                result[i] = (key_node, merged_node)
            else:
                # Otherwise last value wins
                result[i] = (key_node, val_node)
        else:
            key_to_index[key] = len(result)
            result.append((key_node, val_node))
    return result

def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, ValueNode) pairs that may contain duplicate keys.
    """
    # Helper to determine if a node is a MappingNode
    def is_mapping_node(node):
        return hasattr(node, "tag") and hasattr(node, "value") and isinstance(node.value, list)

    # Merge two mapping node values recursively
    def merge_mapping_values(node1, node2):
        merged_list = deep_merge_nodes(node1.value + node2.value)
        return type(node1)(tag=node1.tag, value=merged_list)

    key_to_node = {}
    key_to_first_keynode = {}
    key_order = []

    for key_node, value_node in nodes:
        key = key_node.value

        if key in key_to_node:
            existing_value = key_to_node[key]
            if is_mapping_node(existing_value) and is_mapping_node(value_node):
                new_value = merge_mapping_values(existing_value, value_node)
            else:
                # Last value wins for non-mapping
                new_value = value_node
            key_to_node[key] = new_value
        else:
            key_to_node[key] = value_node
            key_to_first_keynode[key] = key_node
            key_order.append(key)

    merged_nodes = []
    for key in key_order:
        merged_nodes.append((key_to_first_keynode[key], key_to_node[key]))

    return merged_nodes

def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, valueNode) tuples, recursively merging MappingNode values
    with duplicate keys. The last value wins for non-mapping node collisions.
    """
    # Helper to determine if a node is a mapping node
    def is_mapping(node):
        return hasattr(node, "tag") and isinstance(node.tag, str) and node.tag.endswith(":map")

    # Recursive merge of two MappingNode values
    def merge_mapping_nodes(node1, node2):
        # Extract child items
        children1 = getattr(node1, "value", []) or []
        children2 = getattr(node2, "value", []) or []

        merged = {}
        order = []

        for knode, v in children1:
            key = getattr(knode, "value", None)
            if key is None:
                continue
            merged[key] = (knode, v)
            order.append(key)

        for knode, v in children2:
            key = getattr(knode, "value", None)
            if key is None:
                continue
            if key in merged:
                _, existing_v = merged[key]
                if is_mapping(existing_v) and is_mapping(v):
                    merged[key] = (merged[key][0], merge_mapping_nodes(existing_v, v))
                else:
                    merged[key] = (merged[key][0], v)
            else:
                merged[key] = (knode, v)
                order.append(key)

        merged_children = [(merged[k][0], merged[k][1]) for k in order]
        # Construct a new MappingNode with the same tag as the first node
        return ruamel.yaml.nodes.MappingNode(tag=getattr(node1, "tag", None), value=merged_children)

    # Main merge logic
    merged_dict = {}
    merge_order = []

    for knode, v in nodes:
        key = getattr(knode, "value", None)
        if key is None:
            continue

        if key in merged_dict:
            _, existing_v = merged_dict[key]
            if is_mapping(existing_v) and is_mapping(v):
                merged_v = merge_mapping_nodes(existing_v, v)
                merged_dict[key] = (merged_dict[key][0], merged_v)
            else:
                merged_dict[key] = (merged_dict[key][0], v)
        else:
            merged_dict[key] = (knode, v)
            merge_order.append(key)

    result = [(merged_dict[k][0], merged_dict[k][1]) for k in merge_order]
    return result

