def parse_arguments(*unparsed_arguments):
    import argparse
    parser = argparse.ArgumentParser()
    # Ensure parser can recognize subparsers by name
    subparsers = parser.add_subparsers(dest='subparser_name', required=False)
    # Default value for subparser_name when no subparser is used
    parser.set_defaults(subparser_name=None)

    # Parse known (global) arguments to find subparser name if any
    try:
        global_ns, remaining = parser.parse_known_args(unparsed_arguments)
    except SystemExit:
        # argparse may exit due to errors such as -h; re‑raise to let callers handle it
        raise

    result = {'global': global_ns}

    if remaining:
        # The first unknown token should be the subparser name
        sub_name = remaining[0]
        # Attempt to retrieve the subparser by name
        try:
            sub_parser = subparsers._name_parser_map[sub_name]
        except AttributeError:
            # If internal structure changed, fall back to public API
            sub_parser = None
        except KeyError:
            sub_parser = None

        if sub_parser:
            # Parse arguments specific to the subparser
            sub_ns, _ = sub_parser.parse_known_args(remaining[1:])
            result[sub_name] = sub_ns
        else:
            # Unknown subparser; treat all unknown arguments as global
            result['global'].unknown = remaining

    return result

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Returns a tuple of (dict mapping subparser name to parsed namespace,
    a list of remaining arguments not claimed by any subparser).
    """
    if not subparsers:
        return {}, list(unparsed_arguments)

    parsed_dict = {}
    unknown_sets = []

    for name, parser in subparsers.items():
        ns, unknown = parser.parse_known_args(unparsed_arguments)
        parsed_dict[name] = ns
        unknown_sets.append(set(unknown))

    # Determine arguments unknown to all subparsers.
    remaining = []
    for arg in unparsed_arguments:
        if all(arg in unknown_set for unknown_set in unknown_sets):
            remaining.append(arg)

    return parsed_dict, remaining

def deep_merge_nodes(nodes):
    """Deep merge duplicate mapping nodes from a list of YAML nodes."""
    # Helper to merge two values (nodes) recursively
    def _merge_value(a, b):
        # If both are MappingNode, merge their key/value pairs
        if isinstance(a, MappingNode) and isinstance(b, MappingNode):
            # Build a dictionary from the first mapping for quick lookup
            a_dict = {k.value: (k, v) for k, v in a.value}
            seen_keys = set(a_dict.keys())

            # Merge entries from the second mapping
            for k2, v2 in b.value:
                key = k2.value
                if key in a_dict:
                    k1, v1 = a_dict[key]
                    # Merge the values recursively
                    merged_val = _merge_value(v1, v2)
                    a_dict[key] = (k1, merged_val)
                else:
                    a_dict[key] = (k2, v2)
                    seen_keys.add(key)

            # Reconstruct the merged list preserving the order of the first mapping
            merged_list = []
            for k1, _ in a.value:
                key = k1.value
                merged_list.append((k1, a_dict[key][1]))
            # Add any new keys from the second mapping that weren't in the first
            for k2, _ in b.value:
                key = k2.value
                if key not in a_dict:
                    # In this case, the key was added in the loop above,
                    # but we only added it if it was new, so just append.
                    merged_list.append((k2, a_dict[key][1]))

            return MappingNode(tag=a.tag, value=merged_list)

        # If the second value is a MappingNode (or either value is not a mapping),
        # the second value wins (last wins policy)
        return b

    merged_pairs = []
    key_to_index = {}

    for key_node, value_node in nodes:
        key = key_node.value
        if key in key_to_index:
            idx = key_to_index[key]
            old_key_node, old_value_node = merged_pairs[idx]
            merged_value = _merge_value(old_value_node, value_node)
            merged_pairs[idx] = (old_key_node, merged_value)
        else:
            key_to_index[key] = len(merged_pairs)
            merged_pairs.append((key_node, value_node))

    return merged_pairs

def deep_merge_nodes(nodes):
    """
    Merge duplicate keys by deep merging mapping nodes, otherwise keep the latest value.
    """
    def merge_mapping_nodes(n1, n2):
        """Recursively merge two MappingNode objects."""
        merged_pairs = {}
        for pair in n1.value + n2.value:
            k_node, v_node = pair
            key = k_node.value
            if key not in merged_pairs:
                merged_pairs[key] = (k_node, v_node)
            else:
                existing_k, existing_v = merged_pairs[key]
                if isinstance(existing_v, MappingNode) and isinstance(v_node, MappingNode):
                    merged_v = merge_mapping_nodes(existing_v, v_node)
                else:
                    merged_v = v_node
                merged_pairs[key] = (existing_k, merged_v)
        return MappingNode(tag=n1.tag, value=list(merged_pairs.values()))

    result_entries = {}
    key_nodes = {}
    for k_node, v_node in nodes:
        key = k_node.value
        if key not in result_entries:
            result_entries[key] = v_node
            key_nodes[key] = k_node
        else:
            existing_v = result_entries[key]
            if isinstance(existing_v, MappingNode) and isinstance(v_node, MappingNode):
                result_entries[key] = merge_mapping_nodes(existing_v, v_node)
            else:
                result_entries[key] = v_node  # last wins

    merged_list = []
    for key in result_entries:
        merged_list.append((key_nodes[key], result_entries[key]))
    return merged_list

def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, Node) tuples by key, deep‑merging mapping values.
    """
    def merge_nodes(v1, v2):
        # Helper to merge two node values
        if isinstance(v1, MappingNode) and isinstance(v2, MappingNode):
            return merge_mapping_nodes(v1, v2)
        # otherwise, last wins
        return v2

    def merge_mapping_nodes(m1, m2):
        # Merge two MappingNode objects, preserving order from m1
        # Build a dict of key value → index for quick lookup
        key_to_index = {}
        merged = []
        for i, (k, v) in enumerate(m1.value):
            merged.append((k, v))
            key_to_index[k.value] = i

        for k, v in m2.value:
            key = k.value
            if key in key_to_index:
                # Replace existing entry with overridden value
                idx = key_to_index[key]
                merged[idx] = (k, merge_nodes(merged[idx][1], v))
            else:
                # Append new key/value pair
                merged.append((k, v))
                key_to_index[key] = len(merged) - 1

        return MappingNode(m1.tag, merged)

    result = []
    key_index_map = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in key_index_map:
            idx = key_index_map[key]
            existing_key, existing_value = result[idx]
            result[idx] = (existing_key, merge_nodes(existing_value, value_node))
        else:
            result.append((key_node, value_node))
            key_index_map[key] = len(result) - 1

    return result

def deep_merge_nodes(nodes):
    '''Deep merge a list of yaml nodes, keeping the last non-mapping value for duplicate keys.'''

    def merge_mapping_nodes(src, dst):
        '''Recursively merge dst MappingNode into src.'''
        # src and dst are MappingNode objects; merge dst into src
        src_map = {k.value: (k, v) for k, v in src.value}
        for k, v in dst.value:
            key_val = k.value
            if key_val in src_map:
                src_k, src_v = src_map[key_val]
                # Preserve the original key node; merge or replace value
                if isinstance(src_v, MappingNode) and isinstance(v, MappingNode):
                    merge_mapping_nodes(src_v, v)
                else:
                    src_map[key_val] = (src_k, v)  # last value wins
                    # Replace in src.value list
                    for idx, (existing_k, _) in enumerate(src.value):
                        if existing_k.value == key_val:
                            src.value[idx] = (src_k, v)
                            break
            else:
                # Add new key/value pair
                src.value.append((k, v))
                src_map[key_val] = (k, v)

    merged = {}
    order = []

    for key_node, value_node in nodes:
        key = key_node.value
        if key not in merged:
            merged[key] = (key_node, value_node)
            order.append(key)
        else:
            existing_key_node, existing_value = merged[key]
            if isinstance(existing_value, MappingNode) and isinstance(value_node, MappingNode):
                merge_mapping_nodes(existing_value, value_node)
            else:
                merged[key] = (existing_key_node, value_node)  # keep original key node, last value wins

    return [(merged[k][0], merged[k][1]) for k in order]

def deep_merge_nodes(nodes):
    def is_mapping_node(node):
        return hasattr(node, "tag") and node.tag == "tag:yaml.org,2002:map"

    def merge_nodes(node1, node2):
        if is_mapping_node(node1) and is_mapping_node(node2):
            node1.value = merge_mapping_nodes(node1.value, node2.value)
            return node1
        return node2

    def merge_mapping_nodes(a_value, b_value):
        combined = {}
        order = []

        # Add original values from a_value
        for key_node, val_node in a_value:
            key = key_node.value
            combined[key] = (key_node, val_node)
            order.append(key)

        # Merge or add values from b_value
        for key_node, val_node in b_value:
            key = key_node.value
            if key in combined:
                _, existing_val = combined[key]
                merged_val = merge_nodes(existing_val, val_node)
                combined[key] = (key_node, merged_val)
            else:
                combined[key] = (key_node, val_node)
                order.append(key)

        # Build merged list preserving order
        merged_list = []
        for key in order:
            k_node, v_node = combined[key]
            merged_list.append((k_node, v_node))
        return merged_list

    result = {}
    order = []
    for key_node, val_node in nodes:
        key = key_node.value
        if key in result:
            _, existing_val = result[key]
            merged_val = merge_nodes(existing_val, val_node)
            result[key] = (key_node, merged_val)
        else:
            result[key] = (key_node, val_node)
            order.append(key)

    merged = []
    for key in order:
        merged.append(result[key])
    return merged

