def bash_completion():
    import subprocess
    import re
    import textwrap
    try:
        help_output = subprocess.check_output(['borgmatic', '--help'], universal_newlines=True)
    except Exception:
        return "# Unable to retrieve borgmatic help"
    subcommands = []
    for line in help_output.splitlines():
        m = re.match(r'^\s{2}(\w+)', line)
        if m:
            subcommands.append(m.group(1))
    subcommands_str = ' '.join(subcommands)
    script = textwrap.dedent(f'''
    # Bash completion script for borgmatic
    _borgmatic() {{
        local cur prev words cword
        cur="${{COMP_WORDS[COMP_CWORD]}}"
        prev="${{COMP_WORDS[COMP_CWORD-1]}}"
        if [ $COMP_CWORD -eq 1 ]; then
            COMPREPLY=( $(compgen -W "{subcommands_str}" -- "$cur") )
        else
            COMPREPLY=()
        fi
    }}
    complete -F _borgmatic borgmatic
    ''')
    return script.strip()

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        raise TypeError("size must be a str")
    s = size.strip()
    if not s:
        raise ValueError("size string is empty")
    multipliers = {
        "k": 1000,
        "m": 1000 ** 2,
        "g": 1000 ** 3,
        "t": 1000 ** 4,
        "p": 1000 ** 5,
        "e": 1000 ** 6,
    }
    # If last character is a letter, treat it as unit
    if s[-1].isalpha():
        num_part = s[:-1].strip()
        suffix = s[-1].lower()
        try:
            number = float(num_part)
        except ValueError as exc:
            raise ValueError(f"Invalid numeric part in size: {num_part}") from exc
        mult = multipliers.get(suffix)
        if mult is None:
            raise ValueError(f"Unknown size unit: '{suffix}'")
        return int(round(number * mult))
    else:
        # No unit, interpret as plain number
        try:
            return int(float(s))
        except ValueError as exc:
            raise ValueError(f"Invalid numeric size: {s}") from exc

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            result[key] = result.get(key, 0) + value
    return result

