    """Replace custom string URL items with values from url_args.

    The function looks for placeholders in the form `{key}` within the URL
    and substitutes them with the corresponding values from the ``url_args``
    dictionary.  If a placeholder is not found in the dictionary, a
    ``KeyError`` is raised.

    Example:
        url = "/api/items/{item_id}/details?lang={lang}"
        url_args = {"item_id": 42, "lang": "en"}
        result = _replace_url_args(url, url_args)
        # result == "/api/items/42/details?lang=en"
    """
    import re

    pattern = re.compile(r"\{([^{}]+)\}")

    def _sub(match):
        key = match.group(1)
        if key not in url_args:
            raise KeyError(f"Missing URL argument for key: {key}")
        return str(url_args[key])

    return pattern.sub(_sub, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    import re, urllib.parse

    pattern = re.compile(r'\{([^}]+)\}')

    def _repl(match):
        key = match.group(1)
        if key in url_args:
            return urllib.parse.quote(str(url_args[key]))
        # If key not found, keep placeholder unchanged
        return match.group(0)

    return pattern.sub(_repl, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    import re

    if not url_args:
        return url

    def _replace_match(match):
        key = match.group(1)
        # Handles dict-like args
        if isinstance(url_args, dict):
            if key not in url_args:
                raise KeyError(f"Placeholder {{{key}}} not found in arguments for URL: {url}")
            return str(url_args[key])
        # Handles list/tuple positional args
        if isinstance(url_args, (list, tuple)):
            try:
                idx = int(key)
            except ValueError:
                raise KeyError(f"Non‑integer placeholder {{{key}}} cannot be used with positional arguments for URL: {url}")
            if idx < 0 or idx >= len(url_args):
                raise IndexError(f"Index {idx} out of range for URL arguments for URL: {url}")
            return str(url_args[idx])
        # Unsupported type
        raise TypeError(f"Unsupported type for url_args: {type(url_args).__name__}")

    # Replace all {key} patterns in the URL
    return re.sub(r'{([^{}]+)}', _replace_match, url)

