def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters.")
    negative = number < 0
    num = -number if negative else number
    if num == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while num:
            digits.append(alphabet[num % base])
            num //= base
        digits.reverse()
    result = ''.join(digits)
    if padding is not None and len(result) < padding:
        pad_len = padding - len(result)
        result = alphabet[0] * pad_len + result
    if negative:
        result = '-' + result
    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if number < 0:
        raise ValueError("Negative numbers are not supported")
    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters")
    if number == 0:
        encoded = alphabet[0]
    else:
        digits = []
        n = number
        while n:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        encoded = ''.join(reversed(digits))
    if padding is not None:
        pad = alphabet[0]
        if len(encoded) < padding:
            encoded = pad * (padding - len(encoded)) + encoded
    return encoded

