    """Return all subclasses of a class, recursively."""
    all_subs = set()

    def _gather(current):
        for sub in current.__subclasses__():
            if sub not in all_subs:
                all_subs.add(sub)
                _gather(sub)

    _gather(cls)
    return all_subs

