def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting."""
    if platform == 'this':
        import sys
        if sys.platform.startswith('win'):
            platform = 0
        else:
            platform = 1
    if platform:
        # POSIX style splitting
        pattern = re.compile(r'''(?:"([^"]*)"|'([^']*)'|(\S+))''')
    else:
        # Windows/CMD style splitting
        pattern = re.compile(r'''(?:"((?:\\.|[^"\\])*)"|(\S+))''')
    args = []
    for m in pattern.finditer(s):
        if platform:
            if m.group(1) is not None:
                token = m.group(1)
            elif m.group(2) is not None:
                token = m.group(2)
            else:
                token = m.group(3)
        else:
            if m.group(1) is not None:
                token = m.group(1).replace(r'\"', '"').replace(r'\\', '\\')
            else:
                token = m.group(2)
        args.append(token)
    return args

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        import sys
        platform = 1 if sys.platform != 'win32' else 0
    if platform not in (0, 1):
        raise ValueError('platform must be 1 (POSIX) or 0 (Windows/CMD)')
    import shlex
    return shlex.split(s, posix=(platform == 1))

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """
    Given an existing archive_path, uncompress it into a temporary directory
    inside tmp_path and initialize a bare git repository there.
    Returns a file:// URL of the created repository which can be used as an
    origin URL.
    """
    # Generate a unique extraction directory
    ts = subprocess.check_output(["date", "+%s%N"]).decode().strip()
    extract_dir = f"{tmp_path}/extracted_{ts}"
    subprocess.check_call(["mkdir", "-p", extract_dir])

    # Determine the archive type and extract
    if archive_path.endswith((".tar.gz", ".tgz")):
        subprocess.check_call(
            ["tar", "-xzf", archive_path, "-C", extract_dir]
        )
    elif archive_path.endswith(".tar"):
        subprocess.check_call(
            ["tar", "-xf", archive_path, "-C", extract_dir]
        )
    elif archive_path.endswith(".zip"):
        subprocess.check_call(
            ["unzip", "-q", archive_path, "-d", extract_dir]
        )
    else:
        raise ValueError(f"Unsupported archive format: {archive_path}")

    # Initialize a git repository if one isn't present
    git_dir = f"{extract_dir}/.git"
    if subprocess.run(
        ["test", "-d", git_dir], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL
    ).returncode != 0:
        subprocess.check_call(["git", "init"], cwd=extract_dir)

    # Return a file protocol URL that Git can use as a remote
    return f"file://{extract_dir}"}

