import datetime, re
def parse_frequency(frequency):
    if frequency is None or (isinstance(frequency, str) and frequency.strip().lower() == 'always'):
        return None
    if not isinstance(frequency, str):
        raise ValueError(f"Frequency must be a string or None, got {type(frequency)}")
    s = frequency.strip()
    m = re.match(r'^(\d+)\s*([a-zA-Z]+)$', s)
    if not m:
        raise ValueError(f"Cannot parse frequency: {frequency!r}")
    value, unit = m.groups()
    value = int(value)
    unit = unit.lower()
    if unit in ('day', 'days'):
        kwargs = {'days': value}
    elif unit in ('week', 'weeks'):
        kwargs = {'weeks': value}
    elif unit in ('hour', 'hours'):
        kwargs = {'hours': value}
    elif unit in ('minute', 'minutes'):
        kwargs = {'minutes': value}
    elif unit in ('second', 'seconds'):
        kwargs = {'seconds': value}
    elif unit in ('microsecond', 'microseconds'):
        kwargs = {'microseconds': value}
    else:
        raise ValueError(f"Unsupported time unit in frequency: {unit!r}")
    return datetime.timedelta(**kwargs)

