    if frequency is None:
        return None
    freq_str = frequency.strip().lower()
    if freq_str == "always":
        return None
    import re
    match = re.fullmatch(r'\s*(\d+)\s*(\w+)\s*', freq_str)
    if not match:
        raise ValueError(f"Unable to parse frequency: {frequency!r}")
    amount_str, unit = match.groups()
    amount = int(amount_str)
    unit = unit.rstrip('s')  # remove trailing plural 's'
    mapping = {
        'day': 'days',
        'week': 'weeks',
        'hour': 'hours',
        'minute': 'minutes',
        'second': 'seconds',
    }
    if unit not in mapping:
        raise ValueError(f"Unsupported time unit in frequency: {frequency!r}")
    kwargs = {mapping[unit]: amount}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False

    # Common localhost identifiers
    if host.lower() in ('localhost', '127.0.0.1', '::1'):
        return True

    try:
        # Resolve the host to an IP address
        addrs = socket.getaddrinfo(host, None)
        for family, _, _, _, sockaddr in addrs:
            ip = sockaddr[0]
            if ip.startswith('127.') or ip == '::1':
                return True
    except socket.error:
        pass

    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # common localhost identifiers
    localhost_idents = {"localhost", "127.0.0.1", "::1", "0.0.0.0"}
    if host in localhost_idents:
        return True

    try:
        # Resolve the given host to all IP addresses it can have
        resolved_addrs = socket.getaddrinfo(host, None)
    except Exception:
        # If resolution fails we can't be sure it's local
        return False

    # Check if any resolved address is a loopback address
    for family, _, _, _, sockaddr in resolved_addrs:
        try:
            ip = sockaddr[0]
        except Exception:
            continue
        if ip in ("127.0.0.1", "::1", "0.0.0.0"):
            return True

    # Get addresses assigned to the local machine
    try:
        local_addrs = socket.getaddrinfo(socket.gethostname(), None)
    except Exception:
        local_addrs = []

    # If the host matches any local address, it is local
    local_ip_set = {sockaddr[0] for _, _, _, _, sockaddr in local_addrs}
    if host in local_ip_set:
        return True

    return False

def is_local(host):
