    """
    try:
        addrinfo = socket.getaddrinfo(host, None)
    except (socket.gaierror, socket.error):
        return False
    for family, _socktype, _proto, _canonname, sockaddr in addrinfo:
        ip = sockaddr[0]
        if ip == "127.0.0.1" or ip == "::1":
