def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Normalize the host string
        host = host.strip()
        # Handle common keyword
        if host.lower() == "localhost":
            return True

        # Remove scheme if present
        if "://" in host:
            host = host.split("://", 1)[1]

        # Strip brackets for IPv6 literals
        if host.startswith("["):
            host = host.split("]", 1)[0][1:]
        else:
            # Strip port if present
            if ":" in host:
                host = host.split(":", 1)[0]

        # Resolve to all addresses
        for result in socket.getaddrinfo(host, None):
            addr = result[4][0]
            # IPv4 loopback
            if addr == "127.0.0.1" or addr.startswith("127."):
                return True
            # IPv6 loopback
            if addr == "::1":
                return True

        return False
    except Exception:
        return False

def make_find_paths(find_paths):
    transformed = []
    for path in find_paths:
        # If the path already contains a pattern delimiter (":"), leave it untouched.
        if ':' in path:
            transformed.append(path)
        else:
            # Escape any regex characters in the fragment and convert to glob pattern.
            transformed.append(f'sh:**/*{re.escape(path)}*/**')
    return transformed

