def oneline(script, seperator=" && "):
    """
    converts a script to one line command.
    THis is useful to run a single ssh command and pass a one line script.
    """
    if script is None:
        return ""
    # Allow script to be either a string or an iterable of lines
    if isinstance(script, str):
        lines = script.splitlines()
    else:
        lines = list(script)
    # Strip trailing and leading whitespace from each line,
    # ignore empty lines.
    cleaned = [line.strip() for line in lines if line.strip()]
    return seperator.join(cleaned)

def subprocess_run_helper(func, *args, timeout, extra_env=None):
    import subprocess, os
    module_name = func.__module__
    func_name = func.__qualname__.split('.')[0]
    script = f'''import sys, importlib
mod = importlib.import_module(r"{module_name}")
func = getattr(mod, r"{func_name}")
func(*sys.argv[1:])'''
    cmd = ['python', '-c', script] + list(args)
    env = os.environ.copy()
    if extra_env:
        env.update(extra_env)
    return subprocess.run(cmd, timeout=timeout, env=env, text=True)

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Support matcher as a dict or tuple
    if isinstance(matcher, dict):
        name = matcher.get("name")
        default = matcher.get("default")
    elif isinstance(matcher, (list, tuple)):
        if len(matcher) == 0:
            raise ValueError("matcher tuple/list must contain at least the variable name")
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    else:
        raise TypeError("matcher must be a dict or a tuple/list")
    if not isinstance(name, str) or not name:
        raise ValueError("variable name must be a non-empty string")
    value = os.getenv(name)
    if value is None:
        if default is not None:
            return str(default)
        raise KeyError(f"Environment variable '{name}' not set and no default provided")
    return str(value)

def _resolve_string(matcher):
    name = matcher.group(1)
    default = matcher.group(2) if matcher.lastindex and matcher.lastindex >= 2 else None
    value = os.getenv(name)
    if value is None:
        if default is None:
            raise KeyError(f"Missing environment variable: {name}")
        return default
    return value

