    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Determine name and default based on matcher type
    if isinstance(matcher, (list, tuple)):
        if len(matcher) == 1:
            name, default = matcher[0], None
        elif len(matcher) >= 2:
            name, default = matcher[0], matcher[1]
        else:
            raise ValueError("Matcher must contain at least a variable name")
    elif isinstance(matcher, str):
        name, default = matcher, None
    else:
        raise TypeError("Matcher must be a string or a sequence of (name, [default])")

    # Retrieve the environment variable if it exists
    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        else:
            raise KeyError(f"Environment variable '{name}' is not set and no default was provided")

    return value

