def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, (str,)):
        cmd = [commands]
    elif isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        raise ValueError("commands must be a string or a list/tuple of strings")

    if args:
        cmd.extend(list(args))

    if verbose:
        print("Running command:", " ".join(cmd))

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            check=True
        )
        output = result.stdout
        if not hide_stderr:
            output += result.stderr
    except subprocess.CalledProcessError as e:
        output = e.stdout or ""
        if not hide_stderr:
            output += e.stderr or ""
        raise RuntimeError(f"Command '{' '.join(cmd)}' failed with return code {e.returncode}: {output}") from e

    return output

