def load_configurations(config_filenames, overrides=None, resolve_env=True):
    results = {}
    errors = []
    logger = logging.getLogger(__name__)
    import os
    from io import StringIO

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                text = f.read()
            if resolve_env:
                text = os.path.expandvars(text)
            ext = os.path.splitext(fname)[1].lower()
            if ext == ".json":
                import json
                parsed = json.loads(text)
            elif ext in (".yaml", ".yml"):
                try:
                    import yaml
                except ImportError:
                    raise RuntimeError("YAML support requires the 'pyyaml' package.")
                parsed = yaml.safe_load(text)
            elif ext in (".ini", ".conf"):
                import configparser
                parser = configparser.ConfigParser()
                parser.read_file(StringIO(text))
                parsed = {section: dict(parser.items(section)) for section in parser.sections()}
            elif ext == ".toml":
                try:
                    import toml
                except ImportError:
                    raise RuntimeError("TOML support requires the 'toml' package.")
                parsed = toml.loads(text)
            else:
                raise ValueError(f"Unsupported file extension: {ext}")

            if not isinstance(parsed, dict):
                raise ValueError("Parsed configuration is not a dictionary")

            if overrides:
                if isinstance(overrides, dict):
                    parsed.update(overrides)
                elif isinstance(overrides, list):
                    for key_val in overrides:
                        if isinstance(key_val, (list, tuple)) and len(key_val) == 2:
                            key, val = key_val
                            parsed[key] = val
                else:
                    raise TypeError("Overrides must be a dict or list of key/value pairs")

            results[fname] = parsed

        except Exception as exc:
            exc_info = (exc.__class__, exc, exc.__traceback__)
            record = logger.makeRecord(
                name=logger.name,
                level=logging.ERROR,
                fn=fname,
                lineno=0,
                msg=f"Failed to load configuration from {fname}: {exc}",
                args=None,
                exc_info=exc_info
            )
            errors.append(record)

    return results, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import os, json, re, logging
    try:
        import yaml
    except ImportError:
        yaml = None
    configs = {}
    error_records = []

    def _substitute_env(value):
        if not isinstance(value, str):
            return value
        pattern = r'\$\{([A-Za-z0-9_]+)\}'
        def repl(match):
            return os.getenv(match.group(1), match.group(0))
        return re.sub(pattern, repl, value)

    def _apply_env(data):
        if isinstance(data, dict):
            return {k: _apply_env(v) for k, v in data.items()}
        elif isinstance(data, list):
            return [_apply_env(v) for v in data]
        else:
            return _substitute_env(data)

    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                if filename.lower().endswith(('.yaml', '.yml')):
                    if yaml is None:
                        raise RuntimeError('PyYAML is required to parse YAML files.')
                    config = yaml.safe_load(f)
                else:
                    config = json.load(f)
            if not isinstance(config, dict):
                raise ValueError('Configuration must be a dictionary')
            if resolve_env:
                config = _apply_env(config)
            if overrides:
                if isinstance(overrides, dict):
                    config.update(overrides)
                else:
                    raise ValueError('Overrides must be a dict')
            configs[filename] = config
        except Exception as exc:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Failed to load configuration {filename}: {exc}',
                args=None,
                exc_info=exc
            )
            error_records.append(record)
    return configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import os
    import json
    import yaml
    import re
    logger = logging.getLogger(__name__)
    configs = {}
    log_records = []
    env_pattern = re.compile(r"\$\{([^}]+)\}")

    def resolve_env_vars(value):
        if isinstance(value, str):
            def repl(match):
                var_name = match.group(1)
                return os.getenv(var_name, match.group(0))
            return env_pattern.sub(repl, value)
        if isinstance(value, dict):
            return {k: resolve_env_vars(v) for k, v in value.items()}
        if isinstance(value, list):
            return [resolve_env_vars(v) for v in value]
        return value

    for filename in config_filenames:
        try:
            with open(filename, "r", encoding="utf-8") as f:
                content = f.read()
            # Try YAML first, fallback to JSON
            try:
                parsed = yaml.safe_load(content)
            except Exception as yaml_err:
                try:
                    parsed = json.loads(content)
                except Exception as json_err:
                    record = logger.makeRecord(
                        logger.name,
                        logging.ERROR,
                        filename,
                        0,
                        f"Failed to parse file '{filename}': {yaml_err}\n{json_err}",
                        None,
                        None,
                    )
                    log_records.append(record)
                    continue
            if parsed is None:
                parsed = {}
            if overrides:
                parsed.update(overrides)
            if resolve_env:
                parsed = resolve_env_vars(parsed)
            configs[os.path.abspath(filename)] = parsed
        except FileNotFoundError as fnf_err:
            record = logger.makeRecord(
                logger.name,
                logging.ERROR,
                filename,
                0,
                f"Configuration file not found: '{filename}': {fnf_err}",
                None,
                None,
            )
            log_records.append(record)
        except Exception as e:
            record = logger.makeRecord(
                logger.name,
                logging.ERROR,
                filename,
                0,
                f"Error processing configuration file '{filename}': {e}",
                None,
                None,
            )
            log_records.append(record)
    return configs, log_records)

