@classmethod
def from_ticks(cls, ticks, tz=None):
    """Create a time from ticks (nanoseconds since midnight)."""
    if not isinstance(ticks, int):
        raise TypeError(f"ticks must be an int, got {type(ticks).__name__}")
    if ticks < 0 or ticks >= 86400000000000:
        raise ValueError("ticks out of bounds (0 <= ticks < 86400000000000)")
    # If the class can be instantiated directly with ticks, use that
    # Otherwise, convert to a datetime.time for debugging purposes
    try:
        return cls(ticks=ticks, tz=tz)
    except TypeError:
        # Fallback: convert ticks to a time with microsecond precision
        total_seconds, nanoseconds = divmod(ticks, 1_000_000_000)
        hours, remainder = divmod(total_seconds, 3600)
        minutes, seconds = divmod(remainder, 60)
        microseconds = nanoseconds // 1000
        # Import only if needed
        import datetime
        dt_time = datetime.time(
            hour=int(hours), minute=int(minutes), second=int(seconds),
            microsecond=int(microseconds), tzinfo=tz
        )
        # Attach remaining nanoseconds if necessary
        dt_time._nanoseconds = nanoseconds % 1000
        # Create the class instance from the datetime.time object
        return cls(dt_time)

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """
        Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Mapping of supported protocol version tuples to their handler classes
        _SUPPORTED_HANDLERS = {
            (3, 1): BoltV30,
            (3, 5): BoltV35,
            (4, 0): BoltV40,
        }

        # If no specific protocol version is requested, return all supported handlers
        if protocol_version is None:
            return dict(_SUPPORTED_HANDLERS)

        # Ensure the provided protocol_version is a tuple
        if not isinstance(protocol_version, tuple):
            raise TypeError(f"protocol_version must be a tuple or None, got {type(protocol_version).__name__}")

        # Return the handler for the requested protocol version if supported
        if protocol_version in _SUPPORTED_HANDLERS:
            return {protocol_version: _SUPPORTED_HANDLERS[protocol_version]}

        # Unsupported protocol version: return an empty dictionary
        return {}

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers.

    Args:
        protocol_version (tuple|None): Optional specific protocol version
            (e.g. (3, 5)). If None, all supported versions are returned.

    Returns:
        dict: Mapping of protocol version tuples to their handler classes.
            If protocol_version is specified and unsupported, an empty dict
            is returned.

    Raises:
        TypeError: If protocol_version is provided but is not a tuple.
    """
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
            )
        handler = getattr(cls, "_AVAILABLE_PROTOCOLS", {}).get(protocol_version)
        return {protocol_version: handler} if handler else {}
    return dict(getattr(cls, "_AVAILABLE_PROTOCOLS", {}))

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """
        Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.
        """
        # Validate protocol_version
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple (major, minor)")
        # Ensure the class has a registry of handlers
        if not hasattr(cls, "_protocol_registry"):
            # Registry not found; return empty dict
            return {}
        registry = cls._protocol_registry
        # If a specific version was requested
        if protocol_version is not None:
            handler = registry.get(protocol_version)
            return {protocol_version: handler} if handler is not None else {}
        # No specific version requested: return a copy of the registry
        return dict(registry)

@classmethod
def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    # Create an empty Bookmarks instance
    bookmarks = cls()

    # Iterate over each raw value and attempt to convert it to a Bookmark object
    for raw in values:
        if raw is None or raw == "":
            # Skip empty or None entries
            continue
        try:
            # Attempt to create a Bookmark from the raw string
            bookmark = Bookmark.from_raw_value(raw)
        except Exception:
            # If the format is invalid or conversion fails, skip this entry
            continue

        # Add the parsed bookmark to the collection
        # We assume the Bookmarks class has an `add` method or similar
        try:
            bookmarks.add(bookmark)
        except AttributeError:
            # If no add method exists, try appending to an internal list
            if hasattr(bookmarks, "bookmarks"):
                bookmarks.bookmarks.append(bookmark)
            else:
                # As a last resort, store in a generic list attribute
                if not hasattr(bookmarks, "_items"):
                    bookmarks._items = []
                bookmarks._items.append(bookmark)

    return bookmarks

