def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # Treat objects that are inherently sequence-like as is
    if isinstance(seq, (list, tuple, str, bytes, bytearray)):
        return seq, type(seq)

    # Fallback: try to consume the iterator into a list, optionally in chunks
    seq_list = []
    if bufsize is None:
        try:
            seq_list = list(seq)
        except TypeError:
            # seq is not iterable; propagate the error
            raise
    else:
        # Read in chunks of size bufsize
        it = iter(seq)
        import itertools
        while True:
            chunk = tuple(itertools.islice(it, bufsize))
            if not chunk:
                break
            seq_list.extend(chunk)

    return seq_list, type(seq)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a list or tuple, return it unchanged
    if isinstance(seq, (list, tuple)):
        return seq, type(seq).__name__

    # Try converting seq to a list; if seq is not iterable, wrap it in a list
    try:
        seq_list = list(seq)
    except Exception:
        seq_list = [seq]

    # If a buffer size is specified and the sequence is longer, truncate it
    if bufsize is not None:
        try:
            seq_list = seq_list[:bufsize]
        except Exception:
            # In case seq_list is not subscriptable, ignore the truncation
            pass

    return seq_list, type(seq_list).__name__

def _get_seq_with_type(seq, bufsize=None):
