    from collections.abc import Sequence
    # If seq already is a sequence, return it as is
    if isinstance(seq, Sequence):
        return seq, type(seq)
    # Try to consume the iterable and build a list
    try:
        seq_list = list(seq)
    except TypeError:
        # seq is not iterable; return it unchanged
        return seq, type(seq)
    return seq_list, type(seq_list)

