def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.  The returned sequence is derived from
    ``seq`` and will be a sequence type (list, tuple, set, etc.) unless it
    was already a sequence-like object.  ``seq_type`` is the type of the
    returned sequence.
    """
    # If seq is not iterable, return it directly
    try:
        iter(seq)
    except TypeError:
        return seq, type(seq)

    # If seq already behaves like a sequence (has __len__ and __getitem__),
    # use it unchanged.
    if hasattr(seq, "__len__") and hasattr(seq, "__getitem__"):
        return seq, type(seq)

    # For generators or other iterables that are not sequence-like,
    # convert to a list.  If ``bufsize`` is given, read it in chunks.
    if bufsize is None:
        buffer = list(seq)
    else:
        # Import locally because we should not add global imports
        import itertools
        buffer = []
        it = iter(seq)
        while True:
            chunk = list(itertools.islice(it, bufsize))
            if not chunk:
                break
            buffer.extend(chunk)

    return buffer, type(buffer)

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored
    for subsequent use (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram one must explicitly
    recompute the scale if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper to compute the integral of the histogram data.
    def _compute_integral(data):
        if isinstance(data, dict):
            return sum(data.values())
        return sum(data)

    if other is None:
        # Getter: return the current scale (compute if necessary)
        if recompute or not hasattr(self, "_scale") or self._scale is None:
            self._scale = _compute_integral(self._data)
        return self._scale

    # Setter: rescale histogram to a new target integral.
    try:
        target = float(other)
    except (TypeError, ValueError) as exc:
        raise TypeError(f"Scale target must be numeric, got {other!r}") from exc

    # Current scale: use cached value if available, otherwise compute
    current = self._scale if hasattr(self, "_scale") and self._scale is not None else _compute_integral(self._data)

    if current == 0:
        raise LenaValueError("Cannot rescale histogram with zero integral")

    # Compute scaling factor
    factor = target / current

    # Apply scaling to each bin
    if isinstance(self._data, dict):
        for k in self._data:
            self._data[k] *= factor
    else:
        # Assume an iterable (list, numpy array, etc.)
        self._data = [x * factor for x in self._data]

    # Store the new scale and return self for chaining.
    self._scale = target
    return self

def scale(self, other=None):
        """Get or set the scale of the graph.

        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        # Get current scale
        if other is None:
            return getattr(self, "scale", None)

        # Validate that the new scale is numeric
        try:
            new_scale = float(other)
        except Exception:
            raise TypeError("The scale must be a numeric value.")

        # Check that current scale is known and non‑zero
        current_scale = getattr(self, "scale", None)
        if current_scale is None or abs(current_scale) < 1e-12:
            raise ValueError("Graph has unknown or zero scale, cannot rescale.")

        # Compute the factor to adjust the last coordinate
        factor = new_scale / current_scale

        # Rescale data – only the last field (coordinate)
        if hasattr(self, "data") and self.data is not None:
            for row in self.data:
                try:
                    row[-1] *= factor
                except Exception:
                    # If row does not support indexing, skip
                    continue

        # Rescale errors, if present – only the last field
        if hasattr(self, "errors") and self.errors is not None:
            for row in self.errors:
                try:
                    row[-1] *= factor
                except Exception:
                    continue

        # Update the scale attribute
        self.scale = new_scale
        return None

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    # Ensure a make_value function that extracts value(s) from each bin
    if make_value is None:
        def make_value(bin_):
            return bin_.content  # default bin content
    # Determine coordinate calculation based on requested side
    def get_bin_coord(bin_):
        if get_coordinate == "left":
            return bin_.left
        elif get_coordinate == "right":
            return bin_.right
        elif get_coordinate == "middle":
            return (bin_.left + bin_.right) / 2.0
        else:
            raise ValueError(f"Unknown coordinate '{get_coordinate}'")
    # Accumulate points for the graph
    pts = []
    for bin_ in hist.bins:
        x = get_bin_coord(bin_)
        y_vals = make_value(bin_)
        if isinstance(y_vals, (tuple, list)):
            pt = (x, *y_vals)
        else:
            pt = (x, y_vals)
        pts.append(pt)
    # Build the graph with provided field names
    graph = Graph(values=pts, field_names=field_names)
    # Apply scale if requested
    if scale is True:
        graph.scale = hist.scale
    elif scale is not None:
        graph.scale = scale
    return graph

def verifyObject(iface, candidate, tentative=False):
    from zope.interface import Invalid
    import inspect

    # 1. Check that candidate claims to provide the interface, unless tentative.
    if not tentative:
        if not iface.providedBy(candidate):
            raise Invalid(
                f"Candidate {candidate!r} does not provide interface {iface!r}"
            )

    # 2. Gather errors for missing attributes/methods and signature mismatches.
    errors = []

    # 3. Iterate over all names defined in the interface (methods & attributes).
    #    In Zope interfaces, `getNames('attributes')` lists all attribute names.
    #    Attribute names are those that must be implemented on the concrete class.
    for name in iface.getNames("attributes"):
        # Skip names that are not defined on the interface.
        if not hasattr(iface, name):
            continue

        # Check presence on candidate.
        if not hasattr(candidate, name):
            errors.append(f"Missing required member '{name}'")
            continue

        candidate_val = getattr(candidate, name)

        # If the interface attribute is callable, check signature matching.
        interface_val = getattr(iface, name, None)
        if callable(interface_val) and callable(candidate_val):
            try:
                sig_iface = inspect.signature(interface_val)
                sig_candidate = inspect.signature(candidate_val)
                # Compare the signatures ignoring return annotations.
                if sig_iface.parameters != sig_candidate.parameters:
                    errors.append(
                        f"Signature mismatch for method '{name}': "
                        f"expected ({', '.join(sig_iface.parameters)}) "
                        f"but got ({', '.join(sig_candidate.parameters)})"
                    )
            except (ValueError, TypeError):
                # If signatures cannot be obtained or do not exist, ignore.
                pass

    # 4. Raise appropriate errors if any.
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("; ".join(errors))

    # If everything passed, return True.
    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.
    """
    errors = []

    # Step 1: Verify that candidate claims to provide the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                raise zope.interface.Invalid(
                    f"{candidate!r} does not provide {iface.__name__}"
                )
        except Exception as e:
            errors.append(str(e))

    # Step 2: Verify that all declared names on the interface are satisfied
    # by the candidate (methods and attributes).
    for name in iface.names():
        try:
            iface_attr = iface[name]
        except KeyError:
            continue  # ignore names that are not actually defined on the interface

        # Decide whether this is an attribute or a method
        # For simplicity, treat any non-callable as an attribute
        if callable(iface_attr):
            # Method
            if not hasattr(candidate, name):
                errors.append(f"Missing method {name}")
                continue
            candidate_attr = getattr(candidate, name)
            if not callable(candidate_attr):
                errors.append(f"Attribute {name} is not callable")
                continue
            # Compare signatures if possible
            try:
                from inspect import signature, Parameter
                iface_sig = signature(iface_attr)
                cand_sig = signature(candidate_attr)

                # Helper to compare signature parameter lists
                def sig_equal(sig1, sig2):
                    if len(sig1.parameters) != len(sig2.parameters):
                        return False
                    for (k1, p1), (k2, p2) in zip(sig1.parameters.items(), sig2.parameters.items()):
                        if p1.kind != p2.kind:
                            return False
                        # Skip parameter names for 'self' if present
                        if k1 == 'self' and k2 == 'self':
                            continue
                        if p1.kind == Parameter.VAR_POSITIONAL or p1.kind == Parameter.VAR_KEYWORD:
                            continue
                        if p1.annotation != p2.annotation:
                            return False
                    return True

                if not sig_equal(iface_sig, cand_sig):
                    errors.append(
                        f"Signature mismatch for method {name}: "
                        f"iface {iface_sig} vs candidate {cand_sig}"
                    )
            except Exception:
                # If signature extraction fails (e.g., built-ins), ignore comparison
                pass
        else:
            # Attribute
            if not hasattr(candidate, name):
                errors.append(f"Missing attribute {name}")
                continue

    # Step 3: Raise errors if any
    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        raise zope.interface.Invalid("; ".join(errors))

    return True

