def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    import inspect

    # Basic input validation
    if iface is None:
        raise TypeError("iface must not be None")
    if candidate is None:
        raise TypeError("candidate must not be None")

    # Resolve the class to be tested
    cls = candidate if inspect.isclass(candidate) else getattr(candidate, "__class__", None)
    if cls is None:
        raise TypeError(f"Cannot determine class of candidate: {candidate!r}")

    # Non-tentative check: ensure subclass relationship
    if not tentative:
        try:
            if not issubclass(cls, iface):
                raise AssertionError(f"{candidate} does not provide interface {iface}")
        except TypeError:
            # If either candidate or iface is not a class, fall back to duck-typing
            pass
        else:
            return True

    # Tentative (duck-typing) check
    if not inspect.isclass(iface):
        raise TypeError("iface must be a class when tentative is True")

    # Gather abstract methods from iface (works for ABCs and Protocols)
    abstract = getattr(iface, "__abstractmethods__", set())
    # Some protocols may not expose __abstractmethods__, inspect members instead
    if not abstract:
        abstract = {name for name, obj in iface.__dict__.items()
                    if getattr(obj, "__isabstractmethod__", False)}

    # Verify that each required attribute exists on candidate's class
    missing = [name for name in abstract if not hasattr(cls, name)]
    if missing:
        missing_str = ", ".join(missing)
        raise AssertionError(
            f"{candidate} does not implement required attributes/methods for {iface}: "
            f"{missing_str}"
        )
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is given, it must be compatible with all bases.
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit_metaclass must be a type")
        for base in bases:
            base_meta = type(base)
            # the explicit metaclass must be a subclass of the base's metaclass
            # or vice versa, otherwise there is a conflict.
            if not (issubclass(explicit_mc, base_meta) or issubclass(base_meta, explicit_mc)):
                raise TypeError(
                    f"metaclass {explicit_mc.__name__ if hasattr(explicit_mc, '__name__') else explicit_mc} "
                    f"conflicts with metaclass {base_meta.__name__} of base {base!r}"
                )
        return explicit_mc

    # No explicit metaclass: determine the most derived metaclass from bases.
    if not bases:
        return type  # default metaclass

    metaclasses = [type(b) for b in bases]

    # Find all unique metaclasses that are compatible with each other.
    unique_metaclasses = set(metaclasses)

    def compatible(m):
        """True if m is compatible with every metaclass in metaclasses."""
        for other in metaclasses:
            # m and other are compatible if one is subclass of the other.
            if not (issubclass(m, other) or issubclass(other, m)):
                return False
        return True

    compatible_metas = [m for m in unique_metaclasses if compatible(m)]

    if not compatible_metas:
        raise TypeError(
            "metaclass conflict: no common metaclass could be found "
            f"since base metaclasses are {', '.join(m.__name__ for m in metaclasses)}"
        )

    # Select the most derived one: the one that appears earliest in the MRO
    # of the first metaclass.
    first_meta = metaclasses[0]
    for m in first_meta.__mro__:
        if m in compatible_metas:
            return m

    # Fallback: return the first compatible metaclass.
    return compatible_metas[0]

def determineMetaclass(bases, explicit_mc=None):
    if explicit_mc is not None:
        metaclass = explicit_mc
    else:
        if not bases:
            metaclass = type
        else:
            metaclasses = [type(b) for b in bases]
            metaclass = metaclasses[0]
            for mt in metaclasses[1:]:
                if issubclass(mt, metaclass):
                    metaclass = mt
                elif not issubclass(metaclass, mt):
                    conflict = f"metaclass conflict: {metaclass} vs {mt}"
                    raise TypeError(conflict)
    return metaclass

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    if not bases:
        return type
    metaclass = type(bases[0])
    for base in bases[1:]:
        base_meta = type(base)
        if issubclass(metaclass, base_meta):
            continue
        if issubclass(base_meta, metaclass):
            metaclass = base_meta
        else:
            raise TypeError(
                f"metaclass conflict: {metaclass.__name__} not compatible with {base_meta.__name__}"
            )
    return metaclass

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised."""
    if key in self:
        value = self[key]
        del self[key]
        return value
    if default is __marker:
        raise KeyError(key)
    return default

