        if default is __marker:
            raise
        return default
    else:
        del self[key]
        return value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('dictionary is empty')
    # Find the key with the smallest usage count
    min_key = min(self, key=lambda k: self.freq.get(k, 0))
    # Remove it from the dictionary and its frequency record
    value = self.pop(min_key)
    self.freq.pop(min_key, None)
    return (min_key, value)

