def isoparse(self, dt_str):
    """
    Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.
    """
    import re
    from datetime import datetime, timedelta, date
    from dateutil.tz import tzoffset, tzutc

    # Accept strings or byte streams
    if hasattr(dt_str, 'read'):
        dt_str = dt_str.read()
    if isinstance(dt_str, bytes):
        dt_str = dt_str.decode('ascii')

    s = dt_str.strip()
    if not s:
        raise ValueError("Empty ISO-8601 string")

    # Split date and time
    if 'T' in s:
        date_part, time_part = s.split('T', 1)
    elif 't' in s:
        date_part, time_part = s.split('t', 1)
    else:
        date_part, time_part = s, ''

    # Parse date part
    # Uncommon week formats
    m = re.match(r'^(?P<year>\d{4})-?W(?P<week>\d{2})(?:-?(?P<weekday>\d{1}))?$', date_part)
    if m:
        y = int(m.group('year'))
        w = int(m.group('week'))
        wd = int(m.group('weekday')) if m.group('weekday') else 1
        try:
            d = date.fromisocalendar(y, w, wd)
        except Exception as exc:
            raise ValueError(f"Invalid ISO week date: {date_part}") from exc
    else:
        # Common formats
        m = re.match(r'^(?P<year>\d{4})(?:-?)(?P<month>\d{2})?(?:-?)(?P<day>\d{2})?$', date_part)
        if not m:
            raise ValueError(f"Invalid ISO date: {date_part}")
        y = int(m.group('year'))
        month = int(m.group('month')) if m.group('month') else 1
        day = int(m.group('day')) if m.group('day') else 1
        try:
            d = date(y, month, day)
        except Exception as exc:
            raise ValueError(f"Invalid ISO date components: {date_part}") from exc

    # Early return if no time part
    if not time_part:
        return datetime.combine(d, datetime.min.time())

    # Detect timezone part
    tzinfo = None
    # tz part can be at end: Z or ±HH:MM or ±HHMM or ±HH
    tz_match = re.search(r'(?P<tz>Z|[+-]\d{2}(?::?\d{2})?)$', time_part)
    if tz_match:
        tz_str = tz_match.group('tz')
        time_part_clean = time_part[:tz_match.start()]
        if tz_str == 'Z' or re.match(r'^[+-]00:?00?$', tz_str):
            tzinfo = tzutc()
        else:
            sign = 1 if tz_str[0] == '+' else -1
            parts = tz_str[1:]
            if ':' in parts:
                h, m = parts.split(':')
                offset = sign * (int(h)*3600 + int(m)*60)
            else:
                if len(parts) == 4:
                    h = parts[:2]
                    m = parts[2:]
                    offset = sign * (int(h)*3600 + int(m)*60)
                else:
                    offset = sign * int(parts)*3600
            tzinfo = tzoffset(tz_str, offset)
    else:
        time_part_clean = time_part

    # Parse time (hour:minute:second.fraction)
    tm_pattern = r'^(?P<hour>\d{2})(?::?(?P<minute>\d{2}))?(?::?(?P<second>\d{2}))?(?:[.,](?P<fraction>\d{1,6}))?$'
    m = re.match(tm_pattern, time_part_clean)
    if not m:
        raise ValueError(f"Invalid ISO time: {time_part}")

    hour = int(m.group('hour'))
    minute = int(m.group('minute')) if m.group('minute') else 0
    second = int(m.group('second')) if m.group('second') else 0
    fraction = m.group('fraction')
    microsecond = int(fraction.ljust(6, '0')) if fraction else 0

    # Special case: 24:00:00 or 24:00 with no sub second
    if hour == 24:
        if minute or second or fraction:
            raise ValueError("Hour 24 must be followed by 00:00:00 or omit minutes and seconds")
        hour = 0
        d = d + timedelta(days=1)

    return datetime(d.year, d.month, d.day, hour, minute, second, microsecond, tzinfo=tzinfo)

def default_tzinfo(dt, tzinfo):
    if dt.tzinfo is None:
        return dt.replace(tzinfo=tzinfo)
    return dt

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Ensure we are working with a mapping
    if not isinstance(request, dict):
        return False

    # 1. Check public message first
    public_msg = request.get("publicMessage")
    if isinstance(public_msg, dict):
        # Diaspora public messages typically contain a "payload" field
        if "payload" in public_msg:
            return True
        # Some legacy public messages might be marked explicitly
        if public_msg.get("legacyPayload") is True:
            return True

    # 2. Check private message
    private_msg = request.get("privateMessage")
    if isinstance(private_msg, dict):
        if "payload" in private_msg:
            return True
        if private_msg.get("legacyPayload") is True:
            return True

    # 3. Legacy payload check – some requests may not be wrapped in a message
    if request.get("legacyPayload") is True:
        return True
    if request.get("type") == "legacy":
        return True

    return False

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        # If the request carries a legacy flag directly
        if getattr(request, "legacy", False):
            return True

        # If request is a mapping instance
        if isinstance(request, dict):
            # Legacy flag might be nested
            if request.get("legacy", False):
                return True

            msg = request.get("message") or request.get("payload")
            if msg:
                # Nested mapping for legacy due to older payload format
                if isinstance(msg, dict):
                    if msg.get("legacy", False):
                        return True
                    # Public / private flags
                    if msg.get("type") == "public" or msg.get("is_public", False):
                        return True
                    if msg.get("type") == "private" or msg.get("is_private", False):
                        return True

        # If request has attributes (e.g., object with .type .payload)
        if hasattr(request, "message"):
            message = request.message
            # Handle legacy message attribute
            if getattr(message, "legacy", False):
                return True

            # Public / private flags as attributes
            if getattr(message, "is_public", False):
                return True
            if getattr(message, "is_private", False):
                return True

        # In case of unknown structures, attempt to deduce from type string
        if hasattr(request, "type"):
            if request.type in ("public", "private"):
                return True
    except Exception:
        pass

    return False

