def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request.
    Matrix API requests usually start with the path `/_matrix` and may contain a
    JSON body with a `type` field that begins with `m.` (e.g. `m.room.message`).
    Some Matrix clients also send a Bearer token in the Authorization header.
    """
    try:
        # Attempt to get the request path from common attributes
        path = getattr(request, "path", None)
        if path is None:
            path = getattr(request, "uri", None)
        if path is None:
            path = getattr(request, "path_info", None)

        if path and path.startswith("/_matrix"):
            return True

        # If the request contains a JSON body, inspect the `type`
        json_body = getattr(request, "json", None)
        if isinstance(json_body, dict) and "type" in json_body:
            try:
                if str(json_body["type"]).startswith("m."):
                    return True
            except Exception:
                pass

        # Check for a Bearer token in the Authorization header
        headers = getattr(request, "headers", None)
        if headers and isinstance(headers, dict):
            auth_value = headers.get("Authorization") or headers.get("authorization")
            if isinstance(auth_value, str) and auth_value.strip().lower().startswith("bearer"):
                return True
    except Exception:
        # Gracefully ignore any unexpected errors and treat as not a Matrix request
        pass

    return False

