def find_tags(text: str, replacer: callable = None) -> Tuple[Set[str], str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re
    # Find spans of code blocks (triple backticks) and inline code (single backticks)
    code_spans = []
    for m in re.finditer(r'```.*?```', text, re.S):
        code_spans.append((m.start(), m.end()))
    for m in re.finditer(r'`[^`]*`', text):
        code_spans.append((m.start(), m.end()))
    # merge overlapping spans for efficiency
    code_spans.sort()
    merged_spans = []
    for span in code_spans:
        if not merged_spans or span[0] > merged_spans[-1][1]:
            merged_spans.append([span[0], span[1]])
        else:
            merged_spans[-1][1] = max(merged_spans[-1][1], span[1])
    # helper to check if a position is inside any code span
    def in_code(pos: int) -> bool:
        for s, e in merged_spans:
            if s <= pos < e:
                return True
        return False
    tags = set()
    # find tags outside code blocks
    for m in re.finditer(r'\B#(\w+)\b', text):
        if not in_code(m.start()):
            tags.add(m.group(1))
    # if replacer is provided, replace tags outside code blocks
    if replacer is not None:
        def repl(m):
            if not in_code(m.start()):
                return replacer(m.group(1))
            return m.group(0)
        new_text = re.sub(r'\B#(\w+)\b', repl, text)
    else:
        new_text = text
    return tags, new_text

