def verify_relayable_signature(public_key, doc, signature):
    import base64
    from cryptography.hazmat.primitives import hashes, serialization
    from cryptography.hazmat.primitives.asymmetric import padding
    from cryptography.exceptions import InvalidSignature

    # Load public key
    if isinstance(public_key, str):
        # Try loading from PEM string
        try:
            pub_key_obj = serialization.load_pem_public_key(public_key.encode(), backend=None)
        except Exception:
            # If that fails, try loading from a file path
            with open(public_key, 'rb') as f:
                pub_key_obj = serialization.load_pem_public_key(f.read(), backend=None)
    else:
        # Assume it's already a key object
        pub_key_obj = public_key

    # Decode the signature from Base64
    try:
        sig_bytes = base64.b64decode(signature)
    except Exception:
        return False

    # Verify the signature
    try:
        pub_key_obj.verify(
            sig_bytes,
            doc.encode('utf-8'),
            padding.PSS(
                mgf=padding.MGF1(hashes.SHA256()),
                salt_length=padding.PSS.MAX_LENGTH
            ),
            hashes.SHA256()
        )
        return True
    except InvalidSignature:
        return False
    except Exception:
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # First attempt to parse as JSON
    try:
        data = json.loads(document)
        # If JSON parsing is successful, return the original structure
        return data
    except Exception:
        # Not JSON – attempt to parse as XRD (XML)
        try:
            root = ET.fromstring(document)
        except ET.ParseError:
            return {}

        # Helper to strip namespace
        def _local_name(tag: str) -> str:
            return tag.split('}')[-1] if '}' in tag else tag

        subject = ""
        aliases: list[str] = []
        links: list[Dict[str, str]] = []

        for child in root:
            tag = _local_name(child.tag)
            if tag == "Subject":
                subject = child.text or ""
            elif tag == "Alias":
                if child.text:
                    aliases.append(child.text.strip())
            elif tag == "Link":
                link: Dict[str, str] = {}
                # Capture link attributes
                for k, v in child.attrib.items():
                    link[k] = v
                # Capture any nested elements within <Link> as properties
                for sub in child:
                    sub_tag = _local_name(sub.tag)
                    link[sub_tag] = sub.text or ""
                links.append(link)

        return {"subject": subject, "aliases": aliases, "links": links}

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old)."""
    import json
    import xml.etree.ElementTree as ET

    document = document.strip()
    result: Dict[str, object] = {}

    # Try JSON first
    if document.startswith('{'):
        try:
            data = json.loads(document)
            result['resource'] = data.get('subject', '') or data.get('resource', '') or data.get('href', '')
            result['metadata'] = data.get('metadata', {})
            result['links'] = data.get('links', [])
            return result
        except Exception:
            # fall through to XML parsing
            pass

    # Fallback to XRD (XML) parsing
    try:
        root = ET.fromstring(document)
        # Grab namespace mapping if present
        ns = {}
        if root.tag.startswith('{'):
            uri = root.tag[root.tag.find("{")+1:root.tag.rfind("}")]
            ns['ns'] = uri
        else:
            ns['ns'] = ''

        # Extract subject
        subject = root.find('ns:subject', ns)
        if subject is not None and subject.text:
            result['resource'] = subject.text

        # Extract links
        links: list = []
        for link in root.findall('ns:link', ns):
            link_attrib = link.attrib
            link_dict = {k: v for k, v in link_attrib.items()}
            links.append(link_dict)
        result['links'] = links
        # XRD may not provide metadata field explicitly
        result['metadata'] = {}
        return result
    except Exception:
        # If anything goes wrong, return empty dict
        return {}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).
    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    doc = document.lstrip()
