    if doc.startswith("{"):
        try:
            return json.loads(doc)
        except Exception as exc:
            raise ValueError(f"Invalid JSON webfinger content: {exc}") from exc
    # XRD format
    try:
        root = ET.fromstring(document)
    except Exception as exc:
        raise ValueError(f"Invalid XRD XML content: {exc}") from exc

    def localname(tag: str) -> str:
        return tag.split("}", 1)[-1] if "}" in tag else tag

    result: Dict[str, Any] = {}

    # Subject
    subject = None
    for elem in root.iter():
        if localname(elem.tag) == "subject":
            subject = elem.text.strip() if elem.text else None
            break
    if subject:
        result["subject"] = subject

    # Aliases (may appear in multiple <aliases> elements)
    aliases: List[str] = []

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json, xml.etree.ElementTree as ET

    doc = document.strip()
    if not doc:
        return {}

    # JSON format (new)
    if doc[0] in ('{', '['):
        try:
            data = json.loads(doc)
        except json.JSONDecodeError:
            return {}
        subject = data.get('subject')
        aliases = data.get('aliases', [])
        links = data.get('links', [])
        return {"subject": subject, "aliases": aliases, "links": links}

    # XRD format (old)
    try:
        root = ET.fromstring(doc)
    except ET.ParseError:
        return {}

    # Helper to find element text ignoring namespace
    def _find_text(tag_name: str) -> Optional[str]:
        elem = root.find('.//{*}' + tag_name)
        return elem.text if elem is not None else None

    subject = _find_text('subject')

    # Get all <uri> elements inside <aliases>
    alias_elems = root.findall('.//{*}uri')
    aliases = [e.text.strip() for e in alias_elems if e.text and e.text.strip()]

    # Parse all <link> elements
    link_elems = root.findall('.//{*}link')
    links = []
    for le in link_elems:
        link_data: Dict[str, Any] = {}
        for key, val in le.attrib.items():
            link_data[key] = val
        # Store any nested <link> elements' text if present
        for sub in le:
            tag = sub.tag.split('}', 1)[-1]  # strip namespace
            if sub.text:
                link_data[tag] = sub.text.strip()
        links.append(link_data)

    return {"subject": subject, "aliases": aliases, "links": links}

def parse_diaspora_webfinger(document: str) -> Dict:
    import json, xml.etree.ElementTree as ET
    # Try JSON format first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            return data
    except json.JSONDecodeError:
        pass
    # If JSON parsing fails, try XRD (XML) format
    try:
        root = ET.fromstring(document)
    except ET.ParseError as e:
        raise ValueError("Invalid webfinger document") from e
    # Extract namespace if present
    ns = {}
    if root.tag.startswith('{'):
        ns_uri = root.tag.split('}')[0][1:]
        ns = {'xrd': ns_uri}
    # Helper to find elements with or without namespace
    def find(tag_name):
        return root.find(f"xrd:{tag_name}", ns) if ns else root.find(tag_name)
    # Subject
    subject_el = find('Subject')
    subject = subject_el.text if subject_el is not None else None
    # Aliases
    aliases = []
    alias_elems = root.findall('xrd:Alias', ns) if ns else root.findall('Alias')
    for a in alias_elems:
        if a.text:
            aliases.append(a.text)
    # Links
    links = []
    link_elems = root.findall('xrd:Link', ns) if ns else root.findall('Link')
    for e in link_elems:
        link = {}
        for attr in ('rel', 'type', 'href', 'title', 'properties', 'template'):
            if attr in e.attrib:
                link[attr] = e.attrib[attr]
        if e.text:
            link['params'] = e.text.strip()
        links.append(link)
    # Title if present
    title_el = find('Title')
    title = title_el.text if title_el is not None else None
    result: Dict = {'subject': subject, 'links': links}
    if aliases:
        result['aliases'] = aliases
    if title:
        result['title'] = title
    return result

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    if '@' not in handle:
        return None
    domain = handle.split('@', 1)[1]
    resource = f'acct:{handle}'
    urls = [
        f'https://{domain}/.well-known/webfinger?resource={resource}',
        f'http://{domain}/.well-known/webfinger?resource={resource}',
    ]
    for url in urls:
        try:
            resp = requests.get(url, timeout=5, allow_redirects=True)
            if resp.status_code == 200:
                return resp.text
        except Exception:
            continue
    return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        if '@' not in handle:
            return None
        domain = handle.split('@', 1)[1]
        # Build the WebFinger URL
        resource = urllib.parse.quote(f"acct:{handle}")
        url = f"https://{domain}/.well-known/webfinger?resource={resource}"
        req = urllib.request.Request(url, headers={"Accept": "application/json"})
        with urllib.request.urlopen(req, timeout=5) as response:
            if response.status != 200:
                return None
            return response.read().decode("utf-8")
    except Exception:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        import requests
        import json
    except Exception:
        # If requests or json aren't available, nothing we can do
        return None

    if not isinstance(handle, str) or '@' not in handle:
        return None

    # Extract the domain part of the handle
    try:
        domain = handle.split('@', 1)[1]
    except Exception:
        return None

    # Construct the webfinger URL and query parameters
    url = f"https://{domain}/.well-known/webfinger"
    params = {"resource": f"acct:{handle}"}

    try:
        # Perform the HTTP GET request
        response = requests.get(url, params=params, timeout=5)

        # If the response was not successful, return None
        if response.status_code != 200:
            return None

        # Attempt to parse the response as JSON
        try:
            data = response.json()
        except ValueError:
            # If automatic parsing fails, fall back to manual parsing
            data = json.loads(response.text)

        return data if isinstance(data, dict) else None
    except Exception:
        # Any unexpected exception results in None
        return None

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    # URLs to try for host-meta according to the Diaspora spec and HTTP/Webfinger fallbacks
    try_urls = [
        f"https://{host}/.well-known/host-meta",
        f"https://{host}/host-meta",
        f"http://{host}/.well-known/host-meta",
        f"http://{host}/host-meta",
    ]

    headers = {
        "Accept": "application/xrd+xml, application/xml;q=0.9",
        # Optional: identify the client (could be useful for debugging)
        "User-Agent": "Diaspora-Python-Client/1.0",
    }

    for url in try_urls:
        try:
            response = requests.get(url, timeout=10, headers=headers, allow_redirects=True)
            if response.status_code == 200:
                # XRD may accept string input; parse bytes safely.
                content = response.content.decode("utf-8", errors="ignore")
                return XRD(content)
        except Exception:
            # Silently try the next URL if any network/parse error occurs
            continue

    # If none of the URLs returned a valid document, raise an exception
    raise RuntimeError(f"Could not retrieve a valid host-meta from {host}")

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import requests
    from xml.etree import ElementTree as ET

    # Build the well-known host-meta URL
    if not host.startswith(("http://", "https://")):
        url = f"https://{host}/.well-known/host-meta"
    else:
        url = f"{host}/.well-known/host-meta"

    headers = {"Accept": "application/xrd+xml"}
    try:
        response = requests.get(url, headers=headers, timeout=10)
        response.raise_for_status()
    except requests.RequestException as e:
        raise RuntimeError(f"Failed to fetch host-meta from {url}: {e}") from e

    try:
        xrd = ET.fromstring(response.content)
    except ET.ParseError as e:
        raise RuntimeError(f"Failed to parse host-meta XML from {url}: {e}") from e

    return xrd

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        request_func = getattr(__import__("requests"), method.lower())
        response = request_func(url, data=data, timeout=timeout, *args, **kwargs)
        return (response.status_code, None)
    except Exception as exc:
        return (None, exc)

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)
        response.raise_for_status()
        return (response.status_code, None)
    except requests.RequestException as exc:
        # If a response was received, try to extract status code
        status = getattr(exc, "response", None)
        if status is not None:
            status = status.status_code
        else:
            status = None
        return (status, exc)

def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of file paths found in the provided directories that match the given spec_option pattern(s).
    `spec_option` can be a glob-style pattern string (e.g., '*.ini') or an iterable of such patterns.
    """
    import os
    import fnmatch

    # Ensure spec_option is iterable of patterns
    if isinstance(spec_option, str):
        patterns = (spec_option,)
    else:
        patterns = tuple(str(p) for p in spec_option)

    matched_files = []

    for directory in settings_dirs:
        if not os.path.isdir(directory):
            continue
        for root, _, files in os.walk(directory):
            for f in files:
                if any(fnmatch.fnmatch(f, pattern) for pattern in patterns):
                    matched_files.append(os.path.join(root, f))

    return sorted(matched_files)

def list_of_file_names(settings_dirs, spec_option):
    import os
    file_names = []
    for directory in settings_dirs:
        if not os.path.isdir(directory):
            continue
        for entry in os.listdir(directory):
            full_path = os.path.join(directory, entry)
            if not os.path.isfile(full_path):
                continue
            if spec_option is None:
                file_names.append(entry)
            else:
                if isinstance(spec_option, str):
                    if entry.endswith(spec_option):
                        file_names.append(entry)
                elif isinstance(spec_option, (list, tuple)):
                    for suffix in spec_option:
                        if entry.endswith(suffix):
                            file_names.append(entry)
                            break
    return file_names

def list_of_file_names(settings_dirs, spec_option):
    """Return a list of file paths from the given directories that match spec_option pattern."""
    import os
    import fnmatch

    matched_files = []

    for dir_path in settings_dirs:
        if not os.path.isdir(dir_path):
            continue

        for root, dirs, files in os.walk(dir_path):
            for filename in files:
                if spec_option is None or fnmatch.fnmatch(filename, spec_option):
                    matched_files.append(os.path.join(root, filename))

    return matched_files

