def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    The method looks for a top‑level ``include`` key in *parser_dict*.
    The value of ``include`` may be a single group name or a list of
    group names.  For each group name it looks up a dictionary in
    ``self._groups`` (a mapping from group name to the actual dict).
    Those dictionaries are deeply merged into *parser_dict* – nested
    dictionaries are merged recursively – and then the ``include`` key
    is removed from the returned dictionary.
    """
    def _deep_merge(target, source):
        for key, value in source.items():
            if (
                key in target
                and isinstance(target[key], dict)
                and isinstance(value, dict)
            ):
                target[key] = _deep_merge(target[key], value)
            else:
                target[key] = value
        return target

    if 'include' not in parser_dict:
        return parser_dict

    include = parser_dict.pop('include')
    if isinstance(include, str):
        include = [include]

    if not isinstance(include, (list, tuple)):
        raise TypeError(
            "The 'include' directive must be a string or a list of strings."
        )

    for group_name in include:
        group_def = getattr(self, "_groups", {}).get(group_name)
        if group_def is None:
            raise KeyError(f"Included group '{group_name}' not found.")
        parser_dict = _deep_merge(parser_dict, group_def)

    return parser_dict

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        include = parser_dict.get("include")
        if not include:
            return parser_dict

        # Ensure the include value is a dict.
        if not isinstance(include, dict):
            raise ValueError(
                f"Expect include directive to be a dict, got: {type(include).__name__}"
            )

        # Helper function to merge two dictionaries recursively.
        def merge_dicts(base, new):
            for key, val in new.items():
                if key in base:
                    if isinstance(base[key], dict) and isinstance(val, dict):
                        base[key] = merge_dicts(base[key], val)
                    elif isinstance(base[key], list) and isinstance(val, list):
                        base[key] += val
                    else:
                        base[key] = val
                else:
                    base[key] = val
            return base

        # Resolve each entry in the include dict.
        for spec_name, spec_value in include.items():
            if isinstance(spec_value, (str, bytes)):
                # Treat as a relative or absolute path to another spec file.
                spec_path = Path(spec_value)
                if not spec_path.is_absolute():
                    # Resolve relative to the directory of the current spec file.
                    base_dir = getattr(self, "current_spec_dir", Path.cwd())
                    spec_path = (base_dir / spec_path).resolve()
                included_dict = self._parse_spec_file(spec_path)
                parser_dict = merge_dicts(parser_dict, included_dict)
            elif isinstance(spec_value, dict):
                # Direct dictionary inclusion; merge into the current parser dict.
                parser_dict = merge_dicts(parser_dict, spec_value)
            else:
                raise ValueError(
                    f"Include value for '{spec_name}' must be a path or dict, got {type(spec_value).__name__}"
                )

        # Remove the include key after processing.
        parser_dict.pop("include", None)
        return parser_dict

