            if not isinstance(spec_args, list):
                spec_args = []

        for arg_def in spec_args:
            # Support both dict-based and object-based definitions
            if isinstance(arg_def, dict):
                name = arg_def.get("name")
                arg_type = arg_def.get("type")
                env_var = arg_def.get("env", arg_def.get("env_var"))
                default_val = arg_def.get("default")
            else:
                name = getattr(arg_def, "name", None)
                arg_type = getattr(arg_def, "type", None)
                env_var = getattr(arg_def, "env", None) or getattr(arg_def, "env_var", None)
                default_val = getattr(arg_def, "default", None)

            if not name:
                continue

            # Priority 1: environment variable
            value = None
            if env_var and env_var in os.environ:
                value = os.environ[env_var]
                if arg_type:
                    try:
                        value = arg_type(value)
                    except Exception:
                        pass

            # Priority 2: spec defined default
            if value is None:
                if name in spec_defaults:
                    value = spec_defaults[name]
                else:
                    value = default_val

            resolved[name] = value

    # Override with user-supplied arguments if available
    user_args = {}
    if hasattr(self, "args") and isinstance(self.args, dict):
        user_args = self.args
    elif hasattr(self, "kwargs") and isinstance(self.kwargs, dict):
        user_args = self.kwargs

    for key, val in user_args.items():
        resolved[key] = val

    return resolved

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    spec = getattr(self, "spec", None)
    if not spec:
        return defaults
    # Try common attributes that might hold argument specifications
    arg_list = getattr(spec, "arguments", None)
    if arg_list is None:
        arg_list = getattr(spec, "args", None)
    if not arg_list:
        return defaults
    for arg in arg_list:
        # Resolve name
        name = getattr(arg, "name", None)
        if name is None:
            # Some specs use 'argName', 'id', or 'parameter' for the name
            name = getattr(arg, "argName", None) or getattr(arg, "id", None) or getattr(arg, "parameter", None)
        if not name:
            continue
        # Resolve default value: check for 'default' then 'value' then use None
        if hasattr(arg, "default"):
            value = arg.default
        elif hasattr(arg, "value"):
            value = arg.value
        else:
            value = None
        defaults[name] = value
    return defaults

