        return

    # Helper to format and emit a deprecation message.
    def warn(arg, context, replacement):
        msg = f"Argument '{arg}' is deprecated"
        if replacement:
            msg += f" and will be removed in a future release. Use '{replacement}' instead."
        else:
            msg += " and will be removed in a future release."
        msg += f" ({context})"
        try:
            # Prefer a structured logger if available.
            self.logger.warning(msg)
