        if arg in deprecated_args:
            warn(arg, "command line", deprecated_args[arg])

    # Check arguments supplied via an answer file.
    for arg in answer_file_args:
        if arg in deprecated_args:
            warn(arg, "answer file", deprecated_args[arg])

