    """
    Return a list of argument names whose values are considered "silenced".
    An argument is considered silenced if its value is None, an empty string,
    or an empty container (list, tuple, set, or dict). Other falsy values
    (e.g., 0 or False) are not treated as silenced.
    """
    if not isinstance(args, dict):
        return []

    silent_args = []
    for name, value in args.items():
        if value is None:
            silent_args.append(name)
        elif isinstance(value, str) and value.strip() == "":
            silent_args.append(name)
        elif isinstance(value, (list, tuple, set, dict)) and len(value) == 0:
            silent_args.append(name)
    return silent_args

