            # Format a helpful error message.
            if isinstance(args, dict):
                names = ", ".join(str(m) for m in missing)
                raise ValueError(f"Missing required keyword arguments: {names}")
            else:
                indices = ", ".join(str(m) for m in missing)
                raise ValueError(
                    f"Missing required positional arguments at positions: {indices}"
                )

        return True

def validate_requires_args(self, args):
        """Check if all the required arguments have been provided."""
        missing = []
        for name in getattr(self, 'required_args', []):
            if name not in args or args[name] is None:
                missing.append(name)
        if missing:
            raise ValueError(f"Missing required arguments: {', '.join(missing)}")
        return True

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    required = getattr(self, 'requires_args', getattr(self, 'requires', []))
    if not required:
        return
    for key in required:
        if key not in args or args[key] is None:
            raise ValueError(f"Missing required argument: {key}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """
        List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when`` condition
        """
        required_args = []
        for opt in options_spec:
            # Skip non-dict elements
            if not isinstance(opt, dict):
                continue

            name = opt.get('name')
            # Skip if name is missing
            if not name:
                continue

            # Get the required_when condition, if any
            cond = opt.get('required_when')
            if not cond:
                continue

            satisfied = False
            # Condition provided as a callable that accepts (command_name, args)
            if callable(cond):
                try:
                    satisfied = bool(cond(command_name, args))
                except Exception:
                    satisfied = False
            # Condition provided as a dictionary of other arg names that must be present
            elif isinstance(cond, dict):
                satisfied = all(args.get(k) for k in cond)
            # Condition provided as a simple argument name that must be truthy
            elif isinstance(cond, str):
                satisfied = bool(args.get(cond))
            # Unsupported type; skip
            else:
                satisfied = False

            if satisfied:
                required_args.append(name)

        return required_args

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required = []
        for opt in options_spec:
            if not isinstance(opt, dict):
                continue
            cond = opt.get('required_when')
            if cond is None:
                continue
            name = opt.get('name')
            if not name:
                continue

            # Condition can be a tuple/list: (dependency, expected_value)
            if isinstance(cond, (list, tuple)) and len(cond) == 2:
                dep, expected = cond
                if args.get(dep) == expected:
                    required.append(name)
                continue

            # Condition can be a callable that accepts the args dict
            if callable(cond):
                try:
                    if cond(args):
                        required.append(name)
                except Exception:
                    pass
                continue

            # Fallback: if the condition value is a truthy value in args
            if args.get(cond):
                required.append(name)

        return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for key, value in args.items():
        # Determine max length for this argument if defined on the instance.
        max_len = getattr(self, f"{key}_max_length", None)
        if max_len is None:
            continue  # No max length specified for this argument.

        # Handle strings.
        if isinstance(value, str):
            if len(value) > max_len:
                raise ValueError(
                    f"Argument '{key}' exceeds maximum length of {max_len} characters."
                )
        # Handle iterables like lists or tuples.
        elif isinstance(value, (list, tuple)):
            if len(value) > max_len:
                raise ValueError(
                    f"Argument '{key}' exceeds maximum length of {max_len} items."
                )
        # For other types, no length check is performed.

    return True

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified."""
        # Determine the mapping of maximum lengths. Use attribute if present,
        # otherwise fall back to a default dictionary or infinite length.
        max_len_map = getattr(self, 'max_length_map', {})
        for key, val in args.items():
            # Decide which max length to apply
            max_len = max_len_map.get(key)
            if max_len is None:
                # If not specified, skip length check for this field
                continue
            if val is None:
                # None values are considered valid regardless of length
                continue
            # Only string-like objects support len
            try:
                length = len(val)
            except TypeError:
                # Non-iterables cannot be measured; skip
                continue
            if length > max_len:
                raise ValueError(
                    f"Argument '{key}' length {length} exceeds maximum allowed {max_len}"
                )
        return True

def validate_length_args(self, args):
        """
        Check if value of arguments is not longer than length specified.
        Args:
            args: The received arguments (expected as a mapping of argument names to values).
        """
        # Optional: use a class attribute `max_lengths` mapping argument names to their maximum allowed lengths.
        max_lengths = getattr(self, 'max_lengths', {})
        for key, value in args.items():
            # Skip if no maximum length defined for this argument
            max_len = max_lengths.get(key)
            if max_len is None:
                continue
            # Skip None values (they don't have a length)
            if value is None:
                continue
            # Try to get the length of the value; ignore if not applicable
            try:
                if len(value) > max_len:
                    raise ValueError(
                        f"Argument '{key}' exceeds maximum length of {max_len} (got {len(value)})"
                    )
            except TypeError:
                # Value does not support len(); skip length validation for it
                continue

def validate_length_args(self, args):
        """
        Check if the value of arguments is not longer than the length specified
        in the `max_length_args` dictionary of the instance.

        :param args: A mapping of argument names to their values.
        """
        # If no max-length specifications are defined, nothing to validate
        max_length_map = getattr(self, "max_length_args", None)
        if not isinstance(max_length_map, dict):
            return

        for name, value in args.items():
            max_len = max_length_map.get(name)
            if max_len is None:
                continue
            if value is None:
                continue
            try:
                length = len(str(value))
            except Exception:
                # If length cannot be computed, skip validation for this value
                continue
            if length > max_len:
                raise ValueError(
                    f"Argument '{name}' length {length} exceeds maximum allowed {max_len}"
                )
        # Return None (or could return True) to indicate successful validation
        return

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices."""
        # Ensure there is a dictionary mapping argument names to their allowed choices.
        choices_map = getattr(self, "choices", {})
        if not isinstance(args, dict):
            return
        for key, value in args.items():
            # Skip arguments that don't have defined choices
            if key not in choices_map:
                continue
            allowed = choices_map[key]
            # If the value is a collection, validate each entry
            if isinstance(value, (list, tuple, set)):
                for item in value:
                    if item not in allowed:
                        raise ValueError(
                            f"Invalid choice for argument '{key}': {item}. "
                            f"Allowed values: {allowed}"
                        )
            else:
                if value not in allowed:
                    raise ValueError(
                        f"Invalid choice for argument '{key}': {value}. "
                        f"Allowed values: {allowed}"
                    )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.
    :param args: The received arguments.
    """
    # Resolve mapping of argument name -> allowed values.
    if hasattr(self, "arg_spec") and isinstance(self.arg_spec, dict):
        # arg_spec expected to be {name: { ... 'choices': [...] }}
        arg_choices = {
            name: spec.get("choices") for name, spec in self.arg_spec.items()
        }
    elif hasattr(self, "_arg_metadata") and isinstance(self._arg_metadata, dict):
        # Some frameworks use a different attribute name.
        arg_choices = {
            name: spec["choices"]
            for name, spec in self._arg_metadata.items()
            if "choices" in spec
        }
    elif hasattr(self, "choices") and isinstance(self.choices, dict):
        arg_choices = self.choices
    else:
        arg_choices = {}

    # Ensure args is a mapping.
    if not isinstance(args, dict):
        if hasattr(args, "__dict__"):
            args = vars(args)
        else:
            raise TypeError("validate_choices_args expects a mapping or an object with attributes")

    for name, value in args.items():
        if name not in arg_choices or arg_choices[name] is None:
            # No choices defined for this argument – skip validation.
            continue

        allowed = arg_choices[name]
        try:
            # Support callables that provide the list of choices.
            if callable(allowed):
                allowed_values = allowed()
            else:
                allowed_values = allowed
            if not isinstance(allowed_values, (list, tuple, set)):
                # Not an iterable – nothing to validate.
                continue
        except Exception:
            # If obtaining allowed values fails, skip validation for this arg.
            continue

        # Handle arguments that accept multiple values (list/tuple).
        if isinstance(value, (list, tuple)):
            invalid_vals = [v for v in value if v not in allowed_values]
            if invalid_vals:
                raise ValueError(
                    f"Invalid value(s) for argument '{name}': {invalid_vals}. "
                    f"Allowed choices: {allowed_values}"
                )
        else:
            if value not in allowed_values:
                raise ValueError(
                    f"Invalid value for argument '{name}': {value}. "
                    f"Allowed choices: {allowed_values}"
                )

def validate_choices_args(self, args):
    """
    Check if the value(s) of choice arguments are one of the available choices.

    :param args: The received arguments as a mapping from argument name to value(s).
    """
    # If the class does not define any argument metadata, silently accept.
    arg_defs = getattr(self, "arguments", {})
    if not isinstance(arg_defs, dict):
        arg_defs = {}

    for name, value in args.items():
        arg_def = arg_defs.get(name)
        # Skip arguments that are not in the definition.
        if arg_def is None:
            continue

        # Get the allowed choices, if any.
        choices = arg_def.get("choices")
        if choices is None:
            continue  # No choice validation needed.

        # Support iterables of values (e.g., list/tuple/set) as input.
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in choices:
                    raise ValueError(
                        f"Invalid choice for argument '{name}': {v!r}"
                        f" not in allowed choices {choices!r}"
                    )
        else:
            if value not in choices:
                raise ValueError(
                    f"Invalid choice for argument '{name}': {value!r}"
                    f" not in allowed choices {choices!r}"
                )

def validate_choices_args(self, args):
        """
        Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Assume that `self.choices` is a dict mapping argument names
        # to iterables of allowed values.
        if not hasattr(self, 'choices') or not isinstance(self.choices, dict):
            return

        for arg_name, allowed_values in self.choices.items():
            if arg_name not in args:
                continue

            value = args[arg_name]
            # Skip validation if the value is None (e.g., optional argument not provided)
            if value is None:
                continue

            # Support multi-valued arguments
            if isinstance(value, (list, tuple, set)):
                invalid = [v for v in value if v not in allowed_values]
                if invalid:
                    raise ValueError(
                        f"Invalid value(s) for argument '{arg_name}': {invalid}. "
                        f"Allowed choices are: {allowed_values}"
                    )
            else:
                if value not in allowed_values:
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}': {value}. "
                        f"Allowed choices are: {allowed_values}"
                    )

def validate_choices_args(self, args):
        """
        Check if value of choice arguments is one of the available choices.

        :param args: The received arguments (dict or object with a __dict__ attribute).
        """
        # Attempt to get a dictionary of argument values.
        try:
            args_dict = args if isinstance(args, dict) else getattr(args, "__dict__", {})
        except Exception:
            args_dict = {}

        for name, value in args_dict.items():
            # Skip if the argument is not defined in the choices map.
            if name not in getattr(self, "_choices", {}):
                continue

            allowed = self._choices[name]
            if value is None:
                continue

            # Handle collection values (lists, tuples, sets).
            if isinstance(value, (list, tuple, set)):
                invalid = [v for v in value if v not in allowed]
                if invalid:
                    raise ValueError(
                        f"In argument '{name}', values {invalid!r} are not in "
                        f"allowed choices {allowed!r}"
                    )
            else:
                if value not in allowed:
                    raise ValueError(
                        f"In argument '{name}', value {value!r} is not in "
                        f"allowed choices {allowed!r}"
                    )
        return

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Validate argument count if limits are specified
    min_args = getattr(self, "min_args", None)
    max_args = getattr(self, "max_args", None)
    if isinstance(args, (list, tuple)):
        arg_count = len(args)
        if min_args is not None and arg_count < min_args:
            raise ValueError(f"Too few arguments: expected at least {min_args}, got {arg_count}")
        if max_args is not None and arg_count > max_args:
            raise ValueError(f"Too many arguments: expected at most {max_args}, got {arg_count}")

    # If individual argument bounds are defined, validate each value
    min_val = getattr(self, "min_value", None)
    max_val = getattr(self, "max_value", None)
    if min_val is not None or max_val is not None:
        for idx, val in enumerate(args):
            if not isinstance(val, (int, float)):
                continue
            if min_val is not None and val < min_val:
                raise ValueError(f"Argument at position {idx} ({val}) is less than the minimum allowed ({min_val})")
            if max_val is not None and val > max_val:
                raise ValueError(f"Argument at position {idx} ({val}) exceeds the maximum allowed ({max_val})")

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        # Assumes the class defines `min` and/or `max` attributes for numeric checks.
        for key, val in args.items():
            try:
                num = float(val)
            except (TypeError, ValueError):
                # Non‑numeric values are ignored for min/max validation
                continue

            if hasattr(self, "min") and num < self.min:
                raise ValueError(
                    f"Argument '{key}' value {num} is less than the minimum allowed "
                    f"({self.min})."
                )
            if hasattr(self, "max") and num > self.max:
                raise ValueError(
                    f"Argument '{key}' value {num} is greater than the maximum allowed "
                    f"({self.max})."
                )
        return True

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                spec_option):
    """
    Build the complex argument type
    """
    # Resolve the class for type_name
    cls = None
    if hasattr(self, type_name):
        cls = getattr(self, type_name)
    else:
        try:
            mod = __import__(__name__)
            cls = getattr(mod, type_name)
        except (ImportError, AttributeError):
            cls = None

    # Fallback to a simple dynamic class if not found
    if not isinstance(cls, type):
        def _init(self, **kw):
            self.__dict__.update(kw)
        cls = type(
            type_name,
            (object,),
            {"__init__": _init}
        )

    # Prepare arguments for initialization
    init_kwargs = {"subcommand": subcommand, "option_name": option_name}
    if isinstance(spec_option, dict):
        init_kwargs.update(spec_option)
    else:
        init_kwargs["value"] = spec_option

    return cls(**init_kwargs)

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    for raw_arg in args:
        if not raw_arg.startswith("--"):
            # ignore non-long options
            continue
        arg = raw_arg[2:]  # strip leading '--'
        if "=" in arg:
            key, value = arg.split("=", 1)
        else:
            key, value = arg, True
        if key.startswith("control."):
            # key of form control.foo
            ctrl_key = key.split(".", 1)[1]
            control_args[ctrl_key] = value
        elif key.startswith("custom."):
            # custom vars are stored in nested_args with a custom prefix
            custom_key = key.split(".", 1)[1]
            nested_args[f"custom_{custom_key}"] = value
        else:
            nested_args[key] = value
    return control_args, nested_args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not extra_vars:
            return vars_dict
        # If extra_vars is a dictionary, update directly
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
        # Handle iterable of items
        elif isinstance(extra_vars, (list, tuple)):
            for item in extra_vars:
                # If item is a dictionary, merge it
                if isinstance(item, dict):
                    vars_dict.update(item)
                # If item is a 2-element iterable (tuple/list), treat as key/value pair
                elif isinstance(item, (tuple, list)) and len(item) == 2:
                    key, value = item
                    vars_dict[key] = value
                # If item is a string, try to parse key=value
                elif isinstance(item, str) and "=" in item:
                    key, value = item.split("=", 1)
                    vars_dict[key] = value
        return vars_dict

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not extra_vars:
            return vars_dict

        # If a dictionary, simply update the target dict
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict

        # Treat non-dict Types as an iterable of key=value strings or dicts
        if not hasattr(extra_vars, "__iter__") or isinstance(extra_vars, str):
            iterable = [extra_vars]
        else:
            iterable = extra_vars

        for item in iterable:
            # Strings of the form key=value
            if isinstance(item, str) and '=' in item:
                key, val = item.split('=', 1)
                vars_dict[key.strip()] = val.strip()
            # Embedded dictionary entries
            elif isinstance(item, dict):
                vars_dict.update(item)
            # Anything else is ignored
        return vars_dict

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not extra_vars:
            return vars_dict

        import ast
        for item in extra_vars:
            if not isinstance(item, str) or '=' not in item:
                continue
            key, val = item.split('=', 1)
            key = key.strip()
            val = val.strip()
            # Try to interpret the value as a Python literal.
            try:
                parsed_val = ast.literal_eval(val)
            except Exception:
                parsed_val = val
            vars_dict[key] = parsed_val
        return vars_dict

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: Iterable of strings of the form ``key=value``
        :return: The updated dictionary
        """
        if not extra_vars:
            return vars_dict
        for var in extra_vars:
            if '=' not in var:
                # Skip malformed entries or ignore silently
                continue
            key, value = var.split('=', 1)
            vars_dict[key] = value
        return vars_dict

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        :return: Updated vars_dict
        """
        if extra_vars is None:
            return vars_dict
        if not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, str):
                # Try key=value format first
                if '=' in item:
                    key, value = item.split('=', 1)
                    vars_dict[key] = value
                else:
                    # Try to parse as JSON (useful for dict-like strings)
                    try:
                        import json
                        parsed = json.loads(item)
                        if isinstance(parsed, dict):
                            vars_dict.update(parsed)
                        else:
                            raise ValueError
                    except Exception:
                        # If parsing fails, raise a clear error
                        raise ValueError(f"Invalid extra-var string: '{item}'. Expected 'key=value' or JSON dict.")
            else:
                raise TypeError(f"Unsupported type for extra-var: {type(item).__name__}. Expected str or dict.")
        return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI."""
    # Build the base command
    cmd = ['ansible-playbook', playbook_path]

    # Append verbosity
    if verbose:
        # Verbosity level expected to be an integer: 0-4
        cmd.extend(['-' + 'v' * verbose])

    # Append any extra ansible arguments provided by the caller
    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                # Booleans are treated as flags when True
                if value:
                    cmd.append(f'--{key}')
            else:
                cmd.extend([f'--{key}', str(value)])

    # Pass extra_vars as JSON via --extra-vars
    if extra_vars is not None:
        try:
            import json
            extra_vars_json = json.dumps(extra_vars, separators=(',', ':'))
        except Exception:
            # Fallback to string representation if JSON fails
            extra_vars_json = str(extra_vars)
        cmd.extend(['--extra-vars', extra_vars_json])

    # Optional: set up environment variables from the Infrared workspace or plugin
    env = None
    if hasattr(ir_workspace, 'get_ansible_env'):
        env = ir_workspace.get_ansible_env()
    if env and hasattr(ir_plugin, 'get_ansible_env'):
        env.update(ir_plugin.get_ansible_env())

    # Execute the command
    try:
        import subprocess
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            env=env,
            check=False
        )
        return result
    except Exception as exc:
        raise RuntimeError(f"Failed to run ansible-playbook: {exc}") from exc

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    import json, subprocess, os
    # Build base command
    cmd = ["ansible-playbook"]
