    if extra_vars:
        try:
            extra_json = json.dumps(extra_vars)
        except Exception as exc:
            raise ValueError("Unable to serialize extra_vars to JSON") from exc
        cmd.extend(["--extra-vars", extra_json])
    # Add any additional ansible‑playbook arguments
    if ansible_args:
        for key, val in ansible_args.items():
            arg_key = f"--{key.lstrip('-')}"
            if isinstance(val, bool):
                if val:
                    cmd.append(arg_key)
            elif val is None:
                # Treat None as a flag without value
                cmd.append(arg_key)
            else:
                cmd.extend([arg_key, str(val)])
    # Prepare environment (inherit from workspace if needed)
    env = os.environ.copy()
    # Optional: if workspace provides a custom ansible bin or config, inject it
    if hasattr(ir_workspace, "get_ansible_bin"):
        env["ANSIBLE_HOME"] = ir_workspace.get_ansible_bin()
    # Execute command
    try:
        result = subprocess.run(
            cmd,
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            env=env,
        )
    except subprocess.CalledProcessError as exc:
        if verbose:
            print(exc.output, file=exc.stderr)
        raise RuntimeError(f"ansible-playbook returned non‑zero exit status {exc.returncode}") from exc
    # If verbosity requested, print output
    if verbose:
        print(result.stdout)
    return result.stdout

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to correct types by modifying values_dict in-place.
        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of arguments with values initially as strings
        """
        for key, val in list(values_dict.items()):
            # Only attempt conversion for string values
            if isinstance(val, str):
                raw = val.strip()

                # Try integer conversion
                if re.fullmatch(r'^-?\d+$', raw):
                    try:
                        values_dict[key] = int(raw)
                        continue
                    except ValueError:
                        pass

                # Try float conversion
                if re.fullmatch(r'^-?\d+\.\d+$', raw):
                    try:
                        values_dict[key] = float(raw)
                        continue
                    except ValueError:
                        pass

                # Try boolean conversion
                lower = raw.lower()
                if lower in ("true", "false"):
                    values_dict[key] = lower == "true"
                    continue

                # Try JSON decoding (covers lists, dicts, etc.)
                try:
                    decoded = json.loads(raw)
                    values_dict[key] = decoded
                    continue
                except (json.JSONDecodeError, TypeError):
                    pass

        # No return; values_dict is modified in-place.

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.
    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # If the class defines a per‑parser type specification attempt to use it
    type_map = getattr(self, 'arg_type_map', {}).get(parser_name, {})
    for key, raw_value in list(values_dict.items()):
        # If we have an explicit type for this key, try to convert
        if key in type_map:
            expected_type = type_map[key]
            try:
                if expected_type is bool:
                    v = raw_value.strip().lower()
                    if v in ('true', '1', 'yes', 'on'):
                        values_dict[key] = True
                    elif v in ('false', '0', 'no', 'off'):
                        values_dict[key] = False
                    else:
                        # Leave unchanged if we cannot interpret
                        values_dict[key] = raw_value
                elif expected_type is list:
                    # Join with comma separator
                    values_dict[key] = [item.strip() for item in raw_value.split(',')]
                else:
                    values_dict[key] = expected_type(raw_value)
            except Exception:
                # Leave the original string if conversion fails
                pass
            continue

        # Generic heuristics when no explicit mapping is provided
        if isinstance(raw_value, str):
            v = raw_value.strip()
            lv = v.lower()
            if lv in ('true', 'false'):
                values_dict[key] = lv == 'true'
            elif lv == 'none':
                values_dict[key] = None
            else:
                # Try int
                try:
                    values_dict[key] = int(v)
                    continue
                except ValueError:
                    pass
                # Try float
                try:
                    values_dict[key] = float(v)
                    continue
                except ValueError:
                    pass
            # If nothing matched, keep the original string value
            values_dict[key] = v
    # The function mutates values_dict in place and returns nothing
    return None

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # Mapping of expected argument types per parser/command
        type_map = {
            'main': {
                'verbose': bool,
                'threads': int,
                'output': str,
            },
            'virsh': {
                'timeout': int,
                'debug': bool,
                'name': str,
            },
            'ospd': {
                'interval': float,
                'enabled': bool,
                'threshold': int,
            },
        }

        # Retrieve the type mapping for the requested parser
        parser_map = type_map.get(parser_name, {})

        for arg, target_type in parser_map.items():
            if arg not in values_dict:
                continue

            current = values_dict[arg]
            # Skip if value is already the correct type
            if isinstance(current, target_type):
                continue

            try:
                if target_type is bool:
                    # Special handling for boolean conversions from strings
                    if isinstance(current, str):
                        val_lower = current.lower()
                        if val_lower in ('true', '1', 'yes', 'on'):
                            values_dict[arg] = True
                        elif val_lower in ('false', '0', 'no', 'off'):
                            values_dict[arg] = False
                        else:
                            raise ValueError(f"Cannot cast string '{current}' to bool")
                    else:
                        values_dict[arg] = bool(current)
                else:
                    values_dict[arg] = target_type(current)
            except Exception:
                # If casting fails, leave the original value untouched
                pass

        # Method modifies values_dict in place; no explicit return needed.

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import yaml
    import json

    # Determine the plugin spec file
    spec_filenames = ['plugin.yaml', 'plugin.yml', 'plugin.json']
    spec_file = None
    for fname in spec_filenames:
        candidate = os.path.join(plugin_dir, fname)
        if os.path.isfile(candidate):
            spec_file = candidate
            break

    if not spec_file:
        # No spec file found – return an empty dict
        return {}

    # Load the spec content
    try:
        with open(spec_file, 'r', encoding='utf-8') as f:
            if spec_file.endswith('.json'):
                spec_data = json.load(f)
            else:
                spec_data = yaml.safe_load(f) or {}
    except Exception as e:
        raise RuntimeError(f"Failed to load plugin spec from {spec_file}: {e}") from e

    # Recursively flatten the dictionary
    def _flatten(d, parent_key=''):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key))
            else:
                items[new_key] = v
        return items

    return _flatten(spec_data)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os, json

    # Attempt to locate a JSON plugin spec file in common names
    candidate_filenames = [
        "plugin.json",
        "spec.json",
        "plugin.yaml",
        "plugin.yml",
        "spec.yaml",
        "spec.yml",
    ]

    spec_path = None
    for name in candidate_filenames:
        potential = os.path.join(plugin_dir, name)
        if os.path.isfile(potential):
            spec_path = potential
            break

    if not spec_path:
        # No spec file found
        return {}

    # Load spec
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            if spec_path.lower().endswith((".yaml", ".yml")):
                # No yaml module available; fall back to JSON if possible
                try:
                    data = json.load(f)
                except json.JSONDecodeError:
                    # Cannot parse YAML; skip
                    return {}
            else:
                data = json.load(f)
    except Exception:
        # Any I/O or parsing errors result in an empty dict
        return {}

    # Flatten the nested structure
    flat = {}

    def _flatten(prefix, obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                key = f"{prefix}.{k}" if prefix else k
                _flatten(key, v)
        elif isinstance(obj, list):
            for idx, item in enumerate(obj):
                key = f"{prefix}[{idx}]" if prefix else f"[{idx}]"
                _flatten(key, item)
        else:
            flat[prefix] = obj

    _flatten("", data)

    return flat

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    # Support both YAML (plugin.yml) and JSON (plugin.json)
    yaml_path = os.path.join(plugin_dir, "plugin.yml")
    json_path = os.path.join(plugin_dir, "plugin.json")

    data = None
    if os.path.isfile(yaml_path) and yaml is not None:
        with open(yaml_path, "r", encoding="utf-8") as f:
            data = yaml.safe_load(f)
    elif os.path.isfile(json_path):
        with open(json_path, "r", encoding="utf-8") as f:
            data = json.load(f)

    if data is None:
        raise FileNotFoundError(f"No plugin spec (YAML or JSON) found in {plugin_dir}")

    def _flatten(obj, parent_key="", sep="."):
        flattened = {}
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_key = f"{parent_key}{sep}{k}" if parent_key else k
                flattened.update(_flatten(v, new_key, sep=sep))
        elif isinstance(obj, list):
            for idx, item in enumerate(obj):
                new_key = f"{parent_key}{sep}{idx}" if parent_key else str(idx)
                flattened.update(_flatten(item, new_key, sep=sep))
        else:
            flattened[parent_key] = obj
        return flattened

    return _flatten(data)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    # Find a plugin spec file in the given directory
    spec_file_candidates = ("plugin.yaml", "plugin.yml", "plugin.json")
    spec_path = None
    for filename in spec_file_candidates:
        candidate = os.path.join(plugin_dir, filename)
        if os.path.isfile(candidate):
            spec_path = candidate
            break
    if spec_path is None:
        raise FileNotFoundError(f"No plugin spec file (yaml/json) found in {plugin_dir}")

    # Load the spec data
    with open(spec_path, "r", encoding="utf-8") as f:
        if spec_path.endswith(".json"):
            spec_data = json.load(f)
        else:
            if yaml is None:
                raise ImportError("PyYAML is required to load the YAML plugin spec")
            spec_data = yaml.safe_load(f)

    if not isinstance(spec_data, dict):
        raise ValueError("Plugin spec must be a mapping/dict")

    # Recursive flattening
    def _flatten(current, parent_key=""):
        flat = {}
        for key, value in current.items():
            new_key = f"{parent_key}.{key}" if parent_key else key
            if isinstance(value, dict):
                flat.update(_flatten(value, new_key))
            elif isinstance(value, list):
                # Flatten list items, using numeric indices
                for idx, item in enumerate(value):
                    if isinstance(item, dict):
                        flat.update(_flatten(item, f"{new_key}.{idx}"))
                    else:
                        flat[f"{new_key}.{idx}"] = item
            else:
                flat[new_key] = value
        return flat

    return _flatten(spec_data)

def get_plugin_spec_flatten_dict(plugin_dir):
