def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = 'CONFIG_PATH'
    if os.getenv(env_var):
        return
    config_path = getattr(self, 'config_path', None) or getattr(self, 'configFile', None)
    if config_path:
        os.environ[env_var] = str(config_path)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        # Determine a sensible default path for the configuration file.
        # Prefer XDG_CONFIG_HOME if it is set, otherwise fall back to the
        # user's home directory under ~/.config.
        xdg_config_home = os.getenv('XDG_CONFIG_HOME')
        if xdg_config_home:
            default_path = os.path.join(xdg_config_home, 'myapp', 'config.yaml')
        else:
            home_dir = os.path.expanduser('~')
            default_path = os.path.join(home_dir, '.config', 'myapp', 'config.yaml')
        os.environ['CONFIG_PATH'] = default_path

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if not os.getenv("CONFIG_PATH"):
        # Default configuration file relative to this module's directory
        config_path = os.path.join(os.path.dirname(__file__), "config.yaml")
        os.environ["CONFIG_PATH"] = config_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    from pathlib import Path
    if not root:
        raise ValueError("root cannot be empty")
    path_obj = Path(path)
    root_obj = Path(root)
    try:
        rel = path_obj.relative_to(root_obj)
        return str(rel)
    except ValueError:
        raise ValueError(f"Path {path!r} does not start with root {root!r}")

def strip_root(path, root):
    import os
    root = os.path.abspath(root)
    path = os.path.abspath(path)
    try:
        rel = os.path.relpath(path, root)
    except ValueError as exc:
        raise ValueError(f"Cannot strip root '{root}' from path '{path}': {exc}") from exc
    # rel is "." if path == root; treat it as empty string
    if rel == ".":
        return ""
    # If rel starts with '..' or is an absolute path, path is not within root
    if rel.startswith(("..", os.pardir)) or os.path.isabs(rel):
        raise ValueError(f"Path '{path}' is outside the root '{root}'")
    return rel
